/* DAWAH X — ahmad, অধ্যায় 115 · খণ্ড 115 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][115]=[[22801,22801,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏صُهَيْبٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى هَمَسَ شَيْئًا لَا أَفْهَمُهُ وَلَا يُخْبِرُنَا بِهِ قَالَ أَفَطِنْتُمْ لِي قُلْنَا نَعَمْ قَالَ إِنِّي ذَكَرْتُ نَبِيًّا مِنْ الْأَنْبِيَاءِ أُعْطِيَ جُنُودًا مِنْ قَوْمِهِ فَقَالَ مَنْ يُكَافِئُ هَؤُلَاءِ ‏ ‏أَوْ مَنْ يَقُومُ لِهَؤُلَاءِ أَوْ غَيْرَهَا مِنْ الْكَلَامِ ‏ ‏فَأُوحِيَ إِلَيْهِ أَنْ اخْتَرْ لِقَوْمِكَ إِحْدَى ثَلَاثٍ إِمَّا أَنْ نُسَلِّطَ عَلَيْهِمْ عَدُوًّا مِنْ غَيْرِهِمْ أَوْ الْجُوعَ أَوْ الْمَوْتَ فَاسْتَشَارَ قَوْمَهُ فِي ذَلِكَ فَقَالُوا أَنْتَ نَبِيُّ اللَّهِ فَكُلُّ ذَلِكَ إِلَيْكَ ‏ ‏خِرْ ‏ ‏لَنَا فَقَامَ إِلَى الصَّلَاةِ وَكَانُوا إِذَا فَزِعُوا فَزِعُوا إِلَى الصَّلَاةِ فَصَلَّى مَا شَاءَ اللَّهُ قَالَ ثُمَّ قَالَ أَيْ رَبِّ أَمَّا عَدُوٌّ مِنْ غَيْرِهِمْ فَلَا أَوْ الْجُوعُ فَلَا وَلَكِنْ الْمَوْتُ فَسُلِّطَ عَلَيْهِمْ الْمَوْتُ فَمَاتَ مِنْهُمْ سَبْعُونَ أَلْفًا فَهَمْسِي الَّذِي تَرَوْنَ أَنِّي أَقُولُ اللَّهُمَّ بِكَ أُقَاتِلُ وَبِكَ ‏ ‏أُصَاوِلُ ‏ ‏وَلَا ‏ ‏حَوْلَ ‏ ‏وَلَا ‏ ‏قُوَّةَ ‏ ‏إِلَّا بِاللَّهِ ‏","","",""],[22802,22802,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏صُهَيْبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ إِذَا لَقِيَ الْعَدُوَّ ‏ ‏اللَّهُمَّ بِكَ ‏ ‏أَحُولُ ‏ ‏وَبِكَ ‏ ‏أَصُولُ ‏ ‏وَبِكَ أُقَاتِلُ ‏","","",""],[22803,22803,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُحَمَّدِ بْنِ عَقِيلٍ ‏ ‏عَنْ ‏ ‏حَمْزَةَ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏فَقَالَ ‏ ‏لِعُمَرَ ‏ ‏أَمَّا قَوْلُكَ اكْتَنَيْتَ وَلَيْسَ لَكَ وَلَدٌ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَنَّانِي ‏ ‏أَبَا يَحْيَى ‏ ‏فَأَمَّا قَوْلُكَ فِيكَ ‏ ‏سَرَفٌ ‏ ‏فِي الطَّعَامِ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ خَيْرُكُمْ مَنْ أَطْعَمَ الطَّعَامَ ‏ ‏أَوْ الَّذِينَ يُطْعِمُونَ الطَّعَامَ ‏","","",""],[22804,22804,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏صُهَيْبٍ ‏ ‏قَالَ ‏ ‏بَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَاعِدٌ مَعَ أَصْحَابِهِ إِذْ ضَحِكَ فَقَالَ أَلَا تَسْأَلُونِي مِمَّ أَضْحَكُ قَالُوا يَا رَسُولَ اللَّهِ وَمِمَّ تَضْحَكُ قَالَ ‏ ‏عَجِبْتُ لِأَمْرِ الْمُؤْمِنِ إِنَّ أَمْرَهُ كُلَّهُ خَيْرٌ إِنْ أَصَابَهُ مَا يُحِبُّ حَمِدَ اللَّهَ وَكَانَ لَهُ خَيْرٌ وَإِنْ أَصَابَهُ مَا يَكْرَهُ فَصَبَرَ كَانَ لَهُ خَيْرٌ وَلَيْسَ كُلُّ أَحَدٍ أَمْرُهُ كُلُّهُ لَهُ خَيْرٌ إِلَّا الْمُؤْمِنُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَاه ‏ ‏عَفَّانُ ‏ ‏أَيْضًا ‏ ‏حَدَّثَنَاهُ ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏هَذَا اللَّفْظَ بِعَيْنِهِ ‏ ‏وَأُرَاهُ وَهِمَ هَذَا لَفْظُ ‏ ‏حَمَّادٍ ‏ ‏وَقَدْ ‏ ‏حَدَّثَنَا قَالَ ‏ ‏سُلَيْمَانُ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏نَحْوًا مِنْ لَفْظِ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏وَذَلِكَ مِنْ كِتَابِهِ قَرَأَهُ عَلَيْنَا ‏","","",""],[22805,22805,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏صُهَيْبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كَانَ مَلِكٌ فِيمَنْ كَانَ قَبْلَكُمْ وَكَانَ لَهُ سَاحِرٌ فَلَمَّا كَبِرَ السَّاحِرُ قَالَ لِلْمَلِكِ إِنِّي قَدْ كَبِرَتْ سِنِّي وَحَضَرَ أَجَلِي فَادْفَعْ إِلَيَّ غُلَامًا فَلَأُعَلِّمُهُ السِّحْرَ ‏ ‏فَدَفَعَ ‏ ‏إِلَيْهِ غُلَامًا فَكَانَ يُعَلِّمُهُ السِّحْرَ وَكَانَ بَيْنَ السَّاحِرِ وَبَيْنَ الْمَلِكِ رَاهِبٌ فَأَتَى ‏ ‏الْغُلَامُ ‏ ‏عَلَى الرَّاهِبِ فَسَمِعَ مِنْ كَلَامِهِ فَأَعْجَبَهُ نَحْوُهُ وَكَلَامُهُ فَكَانَ إِذَا أَتَى السَّاحِرَ ضَرَبَهُ وَقَالَ مَا ‏ ‏حَبَسَكَ ‏ ‏وَإِذَا أَتَى أَهْلَهُ ضَرَبُوهُ وَقَالُوا مَا ‏ ‏حَبَسَكَ ‏ ‏فَشَكَا ذَلِكَ إِلَى الرَّاهِبِ فَقَالَ إِذَا أَرَادَ السَّاحِرُ أَنْ يَضْرِبَكَ فَقُلْ حَبَسَنِي أَهْلِي وَإِذَا أَرَادَ أَهْلُكَ أَنْ يَضْرِبُوكَ فَقُلْ حَبَسَنِي السَّاحِرُ وَقَالَ فَبَيْنَمَا هُوَ كَذَلِكَ إِذْ أَتَى ذَاتَ يَوْمٍ عَلَى دَابَّةٍ فَظِيعَةٍ عَظِيمَةٍ وَقَدْ حَبَسَتْ النَّاسَ فَلَا يَسْتَطِيعُونَ أَنْ يَجُوزُوا فَقَالَ الْيَوْمَ أَعْلَمُ أَمْرُ الرَّاهِبِ أَحَبُّ إِلَى اللَّهِ أَمْ أَمْرُ السَّاحِرِ فَأَخَذَ حَجَرًا فَقَالَ اللَّهُمَّ إِنْ كَانَ أَمْرُ الرَّاهِبِ أَحَبَّ إِلَيْكَ وَأَرْضَى لَكَ مِنْ السَّاحِرِ فَاقْتُلْ هَذِهِ الدَّابَّةَ حَتَّى يَجُوزَ النَّاسُ وَرَمَاهَا فَقَتَلَهَا وَمَضَى النَّاسُ فَأَخْبَرَ الرَّاهِبَ بِذَلِكَ فَقَالَ أَيْ بُنَيَّ أَنْتَ أَفْضَلُ مِنِّي وَإِنَّكَ ‏ ‏سَتُبْتَلَى ‏ ‏فَإِنْ ‏ ‏ابْتُلِيتَ ‏ ‏فَلَا تَدُلَّ عَلَيَّ فَكَانَ الْغُلَامُ يُبْرِئُ ‏ ‏الْأَكْمَهَ ‏ ‏وَسَائِرَ ‏ ‏الْأَدْوَاءِ ‏ ‏وَيَشْفِيهِمْ وَكَانَ جَلِيسٌ لِلْمَلِكِ فَعَمِيَ فَسَمِعَ بِهِ فَأَتَاهُ بِهَدَايَا كَثِيرَةٍ فَقَالَ اشْفِنِي وَلَكَ مَا هَاهُنَا ‏ ‏أَجْمَعُ ‏ ‏فَقَالَ مَا ‏ ‏أَشْفِي أَنَا أَحَدًا إِنَّمَا ‏ ‏يَشْفِي اللَّهُ عَزَّ وَجَلَّ فَإِنْ أَنْتَ آمَنْتَ بِهِ فَدَعَوْتُ اللَّهَ فَشَفَاكَ فَآمَنَ فَدَعَا اللَّهَ لَهُ فَشَفَاهُ ثُمَّ أَتَى الْمَلِكَ فَجَلَسَ مِنْهُ نَحْوَ مَا كَانَ يَجْلِسُ فَقَالَ لَهُ الْمَلِكُ يَا فُلَانُ مَنْ رَدَّ عَلَيْكَ بَصَرَكَ فَقَالَ رَبِّي قَالَ أَنَا قَالَ لَا لَكِنْ رَبِّي وَرَبُّكَ اللَّهُ قَالَ أَوَلَكَ رَبٌّ غَيْرِي قَالَ نَعَمْ فَلَمْ يَزَلْ يُعَذِّبُهُ حَتَّى دَلَّهُ عَلَى الْغُلَامِ فَبَعَثَ إِلَيْهِ فَقَالَ أَيْ بُنَيَّ قَدْ بَلَغَ مِنْ سِحْرِكَ أَنْ تُبْرِئَ ‏ ‏الْأَكْمَهَ ‏ ‏وَالْأَبْرَصَ وَهَذِهِ ‏ ‏الْأَدْوَاءَ ‏ ‏قَالَ مَا ‏ ‏أَشْفِي أَنَا أَحَدًا مَا ‏ ‏يَشْفِي غَيْرُ اللَّهِ عَزَّ وَجَلَّ قَالَ أَنَا قَالَ لَا قَالَ أَوَلَكَ رَبٌّ غَيْرِي قَالَ نَعَمْ رَبِّي وَرَبُّكَ اللَّهُ فَأَخَذَهُ أَيْضًا بِالْعَذَابِ فَلَمْ يَزَلْ بِهِ حَتَّى دَلَّ عَلَى الرَّاهِبِ فَأَتَى بِالرَّاهِبِ فَقَالَ ارْجِعْ عَنْ دِينِكِ فَأَبَى فَوَضَعَ الْمِنْشَارَ فِي مَفْرِقِ رَأْسِهِ حَتَّى وَقَعَ شِقَّاهُ وَقَالَ لِلْأَعْمَى ارْجِعْ عَنْ دِينِكَ فَأَبَى فَوَضَعَ الْمِنْشَارَ فِي مَفْرِقِ رَأْسِهِ حَتَّى وَقَعَ شِقَّاهُ فِي الْأَرْضِ وَقَالَ لِلْغُلَامِ ارْجِعْ عَنْ دِينِكَ فَأَبَى فَبَعَثَ بِهِ مَعَ نَفَرٍ إِلَى جَبَلِ كَذَا وَكَذَا فَقَالَ إِذَا بَلَغْتُمْ ‏ ‏ذُرْوَتَهُ ‏ ‏فَإِنْ رَجَعَ عَنْ دِينِهِ وَإِلَّا ‏ ‏فَدَهْدِهُوهُ ‏ ‏مِنْ فَوْقِهِ فَذَهَبُوا بِهِ فَلَمَّا عَلَوْا بِهِ الْجَبَلَ قَالَ اللَّهُمَّ ‏ ‏اكْفِنِيهِمْ ‏ ‏بِمَا شِئْتَ ‏ ‏فَرَجَفَ ‏ ‏بِهِمْ الْجَبَلُ ‏ ‏فَدُهْدِهُوا ‏ ‏أَجْمَعُونَ وَجَاءَ الْغُلَامُ يَتَلَمَّسُ حَتَّى دَخَلَ عَلَى الْمَلِكِ فَقَالَ مَا فَعَلَ أَصْحَابُكَ فَقَالَ ‏ ‏كَفَانِيهِمْ ‏ ‏اللَّهُ عَزَّ وَجَلَّ فَبَعَثَهُ مَعَ نَفَرٍ فِي ‏ ‏قُرْقُورٍ ‏ ‏فَقَالَ إِذَا ‏ ‏لَجَجْتُمْ ‏ ‏بِهِ الْبَحْرَ فَإِنْ رَجَعَ عَنْ دِينِهِ وَإِلَّا فَغَرِّقُوهُ ‏ ‏فَلَجَّجُوا ‏ ‏بِهِ الْبَحْرَ فَقَالَ الْغُلَامُ اللَّهُمَّ ‏ ‏اكْفِنِيهِمْ ‏ ‏بِمَا شِئْتَ فَغَرِقُوا أَجْمَعُونَ وَجَاءَ الْغُلَامُ يَتَلَمَّسُ حَتَّى دَخَلَ عَلَى الْمَلِكِ فَقَالَ مَا فَعَلَ أَصْحَابُكَ قَالَ ‏ ‏كَفَانِيهِمْ ‏ ‏اللَّهُ عَزَّ وَجَلَّ ثُمَّ قَالَ لِلْمَلِكِ إِنَّكَ لَسْتَ بِقَاتِلِي حَتَّى تَفْعَلَ مَا آمُرُكَ بِهِ فَإِنْ أَنْتَ فَعَلْتَ مَا آمُرُكَ بِهِ قَتَلْتَنِي وَإِلَّا فَإِنَّكَ لَا تَسْتَطِيعُ قَتْلِي قَالَ وَمَا هُوَ قَالَ تَجْمَعُ النَّاسَ فِي ‏ ‏صَعِيدٍ ‏ ‏ثُمَّ تَصْلُبُنِي عَلَى جِذْعٍ فَتَأْخُذُ سَهْمًا مِنْ ‏ ‏كِنَانَتِي ‏ ‏ثُمَّ قُلْ بِسْمِ اللَّهِ رَبِّ الْغُلَامِ فَإِنَّكَ إِذَا فَعَلْتَ ذَلِكَ قَتَلْتَنِي فَفَعَلَ وَوَضَعَ السَّهْمَ فِي ‏ ‏كَبِدِ ‏ ‏قَوْسِهِ ثُمَّ رَمَى فَقَالَ بِسْمِ اللَّهِ رَبِّ الْغُلَامِ فَوَضَعَ السَّهْمَ فِي ‏ ‏صُدْغِهِ ‏ ‏فَوَضَعَ الْغُلَامُ يَدَهُ عَلَى مَوْضِعِ السَّهْمِ وَمَاتَ فَقَالَ النَّاسُ آمَنَّا بِرَبِّ الْغُلَامِ فَقِيلَ لِلْمَلِكِ أَرَأَيْتَ مَا كُنْتَ تَحْذَرُ فَقَدْ وَاللَّهِ نَزَلَ بِكَ قَدْ آمَنَ النَّاسُ كُلُّهُمْ فَأَمَرَ بِأَفْوَاهِ ‏ ‏السِّكَكِ ‏ ‏فَخُدِّدَتْ فِيهَا ‏ ‏الْأُخْدُودُ ‏ ‏وَأُضْرِمَتْ ‏ ‏فِيهَا النِّيرَانُ وَقَالَ مَنْ رَجَعَ عَنْ دِينِهِ فَدَعُوهُ وَإِلَّا فَأَقْحِمُوهُ ‏ ‏فِيهَا قَالَ فَكَانُوا ‏ ‏يَتَعَادَوْنَ ‏ ‏فِيهَا وَيَتَدَافَعُونَ فَجَاءَتْ امْرَأَةٌ بِابْنٍ لَهَا تُرْضِعُهُ فَكَأَنَّهَا تَقَاعَسَتْ أَنْ تَقَعَ فِي النَّارِ فَقَالَ الصَّبِيُّ يَا ‏ ‏أُمَّهْ اصْبِرِي فَإِنَّكِ عَلَى الْحَقِّ ‏","","",""],[22806,22806,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏وَكَانَتْ قَدْ صَلَّتْ الْقِبْلَتَيْنِ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى أَنْ ‏ ‏يُنْتَبَذَ ‏ ‏التَّمْرُ وَالزَّبِيبُ جَمِيعًا وَقَالَ انْتَبِذْ كُلَّ وَاحِدٍ مِنْهَا وَحْدَهُ ‏","","",""],[22807,22807,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏حَدَّثَنَا ‏ ‏رَبَاحٌ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ اللَّهِ بْنِ كَعْبِ بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏أَنَّ ‏ ‏أُمَّ مُبَشِّرٍ ‏ ‏دَخَلَتْ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَجَعِهِ الَّذِي ‏ ‏قُبِضَ ‏ ‏فِيهِ فَقَالَتْ بِأَبِي وَأُمِّي يَا رَسُولَ اللَّهِ مَا تَتَّهِمُ بِنَفْسِكَ فَإِنِّي لَا أَتَّهِمُ إِلَّا الطَّعَامَ الَّذِي أَكَلَ مَعَكَ ‏ ‏بِخَيْبَرَ ‏ ‏وَكَانَ ابْنُهَا مَاتَ قَبْلَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَأَنَا لَا أَتَّهِمُ غَيْرَهُ هَذَا أَوَانُ قَطْعِ ‏ ‏أَبْهَرِي ‏","","",""],[22808,22808,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏ثُمَامَةَ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏إِلَى أَرْضِ ‏ ‏الرُّومِ ‏ ‏وَكَانَ عَامِلًا ‏ ‏لِمُعَاوِيَةَ ‏ ‏عَلَى ‏ ‏الدَّرْبِ ‏ ‏فَأُصِيبَ ابْنُ عَمٍّ لَنَا فَصَلَّى عَلَيْهِ ‏ ‏فَضَالَةُ ‏ ‏وَقَامَ عَلَى حُفْرَتِهِ حَتَّى وَارَاهُ فَلَمَّا سَوَّيْنَا عَلَيْهِ حُفْرَتَهُ قَالَ أَخِفُّوا عَنْهُ فَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَأْمُرُنَا بِتَسْوِيَةِ الْقُبُورِ ‏","","",""],[22809,22809,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏فَضَالَةَ الْأَنْصَارِيِّ ‏ ‏سَمِعْتُهُ يُحَدِّثُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ عَلَيْهِمْ فِي يَوْمٍ كَانَ يَصُومُهُ ‏ ‏فَدَعَا بِإِنَاءٍ فِيهِ مَاءٌ فَشَرِبَ فَقُلْنَا يَا رَسُولَ اللَّهِ إِنَّ هَذَا الْيَوْمَ كُنْتَ تَصُومُهُ قَالَ أَجَلْ وَلَكِنْ قِئْتُ ‏","","",""],[22810,22810,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏يَزِيدَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ثُمَامَةُ بْنُ شُفَيٍّ الْهَمْدَانِيُّ ‏ ‏قَالَ ‏ ‏غَزَوْنَا أَرْضَ ‏ ‏الرُّومِ ‏ ‏وَعَلَى ذَلِكَ الْجَيْشِ ‏ ‏فَضَالَةُ بْنُ عُبَيْدٍ الْأَنْصَارِيُّ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏فَقَالَ ‏ ‏فَضَالَةُ ‏ ‏خَفِّفُوا فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ بِتَسْوِيَةِ الْقُبُورِ ‏","","",""],[22811,22811,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِئُ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو هَانِئٍ حُمَيْدُ بْنُ هَانِئٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَالِكٍ الْجَنْبِيِّ ‏ ‏حَدَّثَنِي أَنَّهُ سَمِعَ ‏ ‏فَضَالَةَ بْنَ عُبَيْدٍ ‏ ‏صَاحِبَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَمِعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا يَدْعُو فِي الصَّلَاةِ وَلَمْ يَذْكُرْ اللَّهَ عَزَّ وَجَلَّ وَلَمْ يُصَلِّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَجِلَ ‏ ‏هَذَا ثُمَّ دَعَاهُ فَقَالَ لَهُ وَلِغَيْرِهِ ‏ ‏إِذَا صَلَّى أَحَدُكُمْ فَلْيَبْدَأْ بِتَحْمِيدِ رَبِّهِ وَالثَّنَاءِ عَلَيْهِ ثُمَّ لِيُصَلِّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ لِيَدْعُ بَعْدُ بِمَا شَاءَ ‏","","",""],[22812,22812,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِئُ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو هَانِئٍ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَالِكٍ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏فَضَالَةَ بْنَ عُبَيْدٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى بِالنَّاسِ ‏ ‏خَرَّ ‏ ‏رِجَالٌ مِنْ قَامَتِهِمْ فِي الصَّلَاةِ لِمَا بِهِمْ مِنْ ‏ ‏الْخَصَاصَةِ ‏ ‏وَهُمْ مِنْ ‏ ‏أَصْحَابِ الصُّفَّةِ ‏ ‏حَتَّى يَقُولَ ‏ ‏الْأَعْرَابُ ‏ ‏إِنَّ هَؤُلَاءِ مَجَانِينُ فَإِذَا قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصَّلَاةَ انْصَرَفَ إِلَيْهِمْ فَقَالَ لَهُمْ ‏ ‏لَوْ تَعْلَمُونَ مَا لَكُمْ ‏ ‏عِنْدَ اللَّهِ عَزَّ وَجَلَّ لَأَحْبَبْتُمْ لَوْ أَنَّكُمْ تَزْدَادُونَ حَاجَةً ‏ ‏وَفَاقَةً ‏ ‏قَالَ ‏ ‏فَضَالَةُ ‏ ‏وَأَنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ ‏","","",""],[22813,22813,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏وَابْنُ لَهِيعَةَ ‏ ‏قَالَا أَنْبَأَنَا ‏ ‏أَبُو هَانِئٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ رَبَاحٍ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏قَالَ ‏ ‏أُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِقِلَادَةٍ فِيهَا ذَهَبٌ وَخَرَزٌ تُبَاعُ وَهِيَ مِنْ الْغَنَائِمِ ‏ ‏فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالذَّهَبِ الَّذِي فِي الْقِلَادَةِ ‏ ‏فَنُزِعَ ‏ ‏وَحْدَهُ ثُمَّ قَالَ الذَّهَبُ بِالذَّهَبِ وَزْنًا بِوَزْنٍ ‏","","",""],[22814,22814,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو هَانِئٍ ‏ ‏عَنْ ‏ ‏أَبِي عَلِيٍّ الْجَنْبِيِّ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُسَلِّمُ الرَّاكِبُ عَلَى الْمَاشِي وَالْقَلِيلُ عَلَى الْكَثِيرِ ‏","","",""],[22815,22815,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَهِيمُ بْنُ إِسْحَاقَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏حَيْوَةَ بْنِ شُرَيْحٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو هَانِئٍ الْخَوْلَانِيُّ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ مَالِكٍ الْجَنْبِيَّ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏فَضَالَةَ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَاتَ عَلَى مَرْتَبَةٍ مِنْ هَذِهِ الْمَرَاتِبِ بُعِثَ عَلَيْهَا ‏ ‏قَالَ ‏ ‏حَيْوَةُ ‏ ‏يَقُولُ ‏ ‏رِبَاطٌ حَجٌّ ‏ ‏أَوْ نَحْوُ ذَلِكَ ‏","","",""],[22816,22816,"","","‏ ‏و حَدَّثَنَاه ‏ ‏الطَّالَقَانِيُّ ‏ ‏فِي هَذَا الْإِسْنَادِ ‏ ‏عَنِ ‏ ‏ابْنِ الْمُبَارَكِ ‏ ‏قَالَ ‏ ‏يُسَلِّمُ الْفَارِسُ عَلَى الْمَاشِي وَالْمَاشِي عَلَى الْقَائِمِ وَالْقَلِيلُ عَلَى الْكَثِيرِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو هَانِئٍ ‏ ‏أَنَّ ‏ ‏أَبَا عَلِيٍّ عَمْرَو بْنَ مَالِكٍ الْجَنْبِيَّ ‏ ‏مِثْلَهُ ‏","","",""],[22817,22817,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو هَانِئٍ ‏ ‏أَنَّ ‏ ‏أَبَا عَلِيٍّ عَمْرَو بْنَ مَالِكٍ الْجَنْبِيَّ ‏ ‏حَدَّثَهُ ‏ ‏فَضَالَةُ بْنُ عُبَيْدٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏ثَلَاثَةٌ لَا تَسْأَلْ عَنْهُمْ رَجُلٌ فَارَقَ الْجَمَاعَةَ وَعَصَى إِمَامَهُ وَمَاتَ عَاصِيًا وَأَمَةٌ ‏ ‏أَوْ عَبْدٌ ‏ ‏أَبَقَ ‏ ‏فَمَاتَ وَامْرَأَةٌ غَابَ عَنْهَا زَوْجُهَا قَدْ كَفَاهَا ‏ ‏مُؤْنَةَ ‏ ‏الدُّنْيَا فَتَبَرَّجَتْ بَعْدَهُ فَلَا تَسْأَلْ عَنْهُمْ وَثَلَاثَةٌ لَا تَسْأَلْ عَنْهُمْ رَجُلٌ نَازَعَ اللَّهَ عَزَّ وَجَلَّ رِدَاءَهُ فَإِنَّ رِدَاءَهُ الْكِبْرِيَاءُ وَإِزَارَهُ الْعِزَّةُ وَرَجُلٌ شَكَّ فِي أَمْرِ اللَّهِ وَالْقَنُوطُ مِنْ رَحْمَةِ اللَّهِ ‏","","",""],[22818,22818,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو هَانِئٍ ‏ ‏أَنَّ ‏ ‏أَبَا عَلِيٍّ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏فَضَالَةَ بْنَ عُبَيْدٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏طُوبَى لِمَنْ هُدِيَ إِلَى الْإِسْلَامِ وَكَانَ عَيْشُهُ كَفَافًا وَقَنَعَ ‏","","",""],[22819,22819,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏وَابْنُ لَهِيعَةَ ‏ ‏قَالَا أَنْبَأَنَا ‏ ‏أَبُو هَانِئٍ ‏ ‏أَنَّ ‏ ‏أَبَا عَلِيٍّ الْجَنْبِيَّ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏فَضَالَةَ بْنَ عُبَيْدٍ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ مَاتَ عَلَى مَرْتَبَةٍ مِنْ هَذِهِ الْمَرَاتِبِ بُعِثَ عَلَيْهَا يَوْمَ الْقِيَامَةِ ‏","","",""],[22820,22820,"","","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ عَلِيٍّ الْمُقَدَّمِيُّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَجَّاجًا ‏ ‏يَذْكُرُ عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مُحَيْرِيزٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِفَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏أَرَأَيْتَ تَعْلِيقَ يَدِ السَّارِقِ فِي الْعُنُقِ أَمِنَ السُّنَّةِ قَالَ نَعَمْ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِسَارِقٍ فَأَمَرَ بِهِ فَقُطِعَتْ يَدُهُ ثُمَّ أَمَرَ بِهَا فَعُلِّقَتْ فِي عُنُقِهِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏وَكَانَ ‏ ‏فَضَالَةُ ‏ ‏مِمَّنْ بَايَعَ تَحْتَ الشَّجَرَةِ ‏ ‏قَالَ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏عَبْد اللَّهِ بْن أَحْمَد ‏ ‏قُلْتُ ‏ ‏لِيَحْيَى بْنِ مَعِينٍ ‏ ‏سَمِعْتَ مِنْ ‏ ‏عُمَرَ بْنِ عَلِيٍّ الْمُقَدَّمِيِّ ‏ ‏شَيْئًا قَالَ أَيُّ شَيْءٍ كَانَ عِنْدَهُ قُلْتُ حَدِيثُ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏فِي تَعْلِيقِ الْيَدِ فَقَالَ لَا حَدَّثَنَا بِهِ ‏ ‏عَفَّانُ ‏ ‏عَنْهُ ‏","","",""],[22821,22821,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ الطَّالَقَانِيُّ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَلَّهُ أَشَدُّ أَذَنًا إِلَى الرَّجُلِ حَسَنِ الصَّوْتِ بِالْقُرْآنِ مِنْ صَاحِبِ ‏ ‏الْقَيْنَةِ ‏ ‏إِلَى قَيْنَتِهِ ‏","","",""],[22822,22822,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ إِسْحَاقَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَصْبَحَ صَائِمًا فَدَعَا بِشَرَابٍ فَقَالَ لَهُ بَعْضُ أَصْحَابِهِ يَا رَسُولَ اللَّهِ أَلَمْ تُصْبِحْ صَائِمًا قَالَ بَلَى وَلَكِنْ قِئْتُ ‏","","",""],[22823,22823,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو هَانِئٍ ‏ ‏عَنْ ‏ ‏أَبِي عَلِيٍّ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُسَلِّمُ الرَّاكِبُ عَلَى الْمَاشِي وَالْمَاشِي عَلَى الْقَاعِدِ وَالْقَلِيلُ عَلَى الْكَثِيرِ ‏","","",""],[22824,22824,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏حَيْوَةَ بْنِ شُرَيْحٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو هَانِئٍ الْخَوْلَانِيُّ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ مَالِكٍ الْجَنْبِيَّ ‏ ‏أَخْبَرَهُ أَنَّهُ سَمِعَ ‏ ‏فَضَالَةَ بْنَ عُبَيْدٍ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَاتَ عَلَى مَرْتَبَةٍ مِنْ هَذِهِ الْمَرَاتِبِ بُعِثَ عَلَيْهَا يَوْمَ الْقِيَامَةِ ‏ ‏قَالَ ‏ ‏حَيْوَةُ ‏ ‏يَقُولُ ‏ ‏رِبَاطٌ ‏ ‏أَوْ حَجٌّ أَوْ نَحْوُ ذَلِكَ ‏","","",""],[22825,22825,"","","‏ ‏وَبِهَذَا الْإِسْنَادِ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كُلُّ مَيِّتٍ يُخْتَمُ عَلَى عَمَلِهِ إِلَّا الَّذِي مَاتَ مُرَابِطًا فِي سَبِيلِ اللَّهِ فَإِنَّهُ ‏ ‏يَنْمُو عَمَلُهُ إِلَى يَوْمِ الْقِيَامَةِ وَيَأْمَنُ ‏ ‏فِتْنَةَ ‏ ‏الْقَبْرِ ‏","","",""],[22826,22826,"","","‏ ‏قَالَ ‏ ‏وَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمُجَاهِدُ مَنْ جَاهَدَ نَفْسَهُ لِلَّهِ ‏ ‏أَوْ قَالَ فِي اللَّهِ ‏ ‏عَزَّ وَجَلَّ ‏","","",""],[22827,22827,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ أَبِي الصَّعْبَةِ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ شَابَ شَيْبَةً فِي سَبِيلِ اللَّهِ كَانَتْ نُورًا لَهُ يَوْمَ الْقِيَامَةِ فَقَالَ رَجُلٌ عِنْدَ ذَلِكَ فَإِنَّ رِجَالًا يَنْتِفُونَ الشَّيْبَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ شَاءَ فَلْيَنْتِفْ نُورَهُ ‏","","",""],[22828,22828,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مُعَاوِيَةُ بْنُ سَعِيدٍ التُّجِيبِيُّ ‏ ‏عَمَّنْ ‏ ‏حَدَّثَهُ عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏الْعَبْدُ آمِنٌ مِنْ عَذَابِ اللَّهِ عَزَّ وَجَلَّ مَا اسْتَغْفَرَ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[22829,22829,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏رِشْدِينُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ هَانِئٍ الْخَوْلَانِيُّ ‏ ‏أَنَّ ‏ ‏عَمْرَو بْنَ مَالِكٍ ‏ ‏حَدَّثَهُ أَنَّهُ سَمِعَ ‏ ‏فَضَالَةَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏كُلُّ مَيِّتٍ يُخْتَمُ عَلَى عَمَلِهِ إِلَّا الْمُرَابِطَ فِي سَبِيلِ اللَّهِ يَجْرِي عَلَيْهِ أَجْرُهُ حَتَّى يَوْمَ الْقِيَامَةِ ‏ ‏وَيُوقَى فِتْنَةَ الْقَبْرِ ‏","","",""],[22830,22830,"","","‏ ‏حَدَّثَنَا ‏ ‏عِصَامُ بْنُ خَالِدٍ الْحَضْرَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏شُرَيْحِ بْنِ عُبَيْدٍ ‏ ‏أَنَّ ‏ ‏فَضَالَةَ بْنَ عُبَيْدٍ الْأَنْصَارِيَّ ‏ ‏كَانَ ‏ ‏يَقُولُ ‏ ‏غَزَوْنَا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَزْوَةَ ‏ ‏تَبُوكَ ‏ ‏فَجَهَدَ بِالظَّهْرِ جَهْدًا شَدِيدًا فَشَكَوْا إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا بِظَهْرِهِمْ مِنْ الْجَهْدِ ‏ ‏فَتَحَيَّنَ ‏ ‏بِهِمْ ‏ ‏مَضِيقًا ‏ ‏فَسَارَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ فَقَالَ ‏ ‏مُرُّوا بِسْمِ اللَّهِ فَمَرَّ النَّاسُ عَلَيْهِ بِظَهْرِهِمْ فَجَعَلَ يَنْفُخُ بِظَهْرِهِمْ اللَّهُمَّ احْمِلْ عَلَيْهَا فِي سَبِيلِكَ إِنَّكَ تَحْمِلُ عَلَى الْقَوِيِّ وَالضَّعِيفِ وَعَلَى الرَّطْبِ وَالْيَابِسِ فِي الْبَرِّ وَالْبَحْرِ قَالَ فَمَا بَلَغْنَا ‏ ‏الْمَدِينَةَ ‏ ‏حَتَّى جَعَلَتْ تُنَازِعُنَا أَزِمَّتَهَا ‏ ‏قَالَ ‏ ‏فَضَالَةُ ‏ ‏هَذِهِ دَعْوَةُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْقَوِيِّ وَالضَّعِيفِ فَمَا بَالُ الرَّطْبِ وَالْيَابِسِ فَلَمَّا قَدِمْنَا ‏ ‏الشَّامَ ‏ ‏غَزَوْنَا غَزْوَةَ ‏ ‏قُبْرُسَ ‏ ‏فِي الْبَحْرِ فَلَمَّا رَأَيْتُ السُّفُنَ فِي الْبَحْرِ وَمَا يَدْخُلُ فِيهَا عَرَفْتُ دَعْوَةَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[22831,22831,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَوْزَاعِيُّ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ عُبَيْدِ اللَّهِ بْنِ أَبِي الْمُهَاجِرِ ‏ ‏عَنْ ‏ ‏مَيْسَرَةَ ‏ ‏مَوْلَى ‏ ‏فَضَالَةَ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَلَّهُ عَزَّ وَجَلَّ أَشَدُّ أَذَنًا لِلرَّجُلِ الْحَسَنِ الصَّوْتِ بِالْقُرْآنِ مِنْ صَاحِبِ ‏ ‏الْقَيْنَةِ ‏ ‏إِلَى ‏ ‏قَيْنَتِهِ ‏","","",""],[22832,22832,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْيَمَانِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ يَعْنِي ابْنَ أَبِي مَرْيَمَ ‏ ‏عَنِ ‏ ‏الْأَشْيَاخِ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏عَلَّمَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُقْيَةً وَأَمَرَنِي أَنْ أَرْقِيَ بِهَا مَنْ بَدَا لِي قَالَ قُلْ رَبَّنَا اللَّهُ الَّذِي فِي السَّمَوَاتِ تَقَدَّسَ اسْمُكَ أَمْرُكَ فِي السَّمَاءِ وَالْأَرْضِ اللَّهُمَّ كَمَا أَمْرُكَ فِي السَّمَاءِ فَاجْعَلْ رَحْمَتَكَ عَلَيْنَا فِي الْأَرْضِ اللَّهُمَّ رَبَّ الطَّيِّبِينَ اغْفِرْ لَنَا ‏ ‏حَوْبَنَا ‏ ‏وَذُنُوبَنَا وَخَطَايَانَا وَنَزِّلْ رَحْمَةً مِنْ رَحْمَتِكَ وَشِفَاءً مِنْ شِفَائِكَ عَلَى مَا بِفُلَانٍ مِنْ شَكْوَى فَيَبْرَأُ قَالَ وَقُلْ ذَلِكَ ثَلَاثًا ثُمَّ تَعَوَّذْ بِالْمُعَوِّذَتَيْنِ ثَلَاثَ مَرَّاتٍ ‏","","",""],[22833,22833,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏لَيْثٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَبُو هَانِئٍ الْخَوْلَانِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَالِكٍ الْجَنْبِيِّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏فَضَالَةُ بْنُ عُبَيْدٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حَجَّةِ الْوَدَاعِ ‏ ‏أَلَا أُخْبِرُكُمْ بِالْمُؤْمِنِ مَنْ أَمِنَهُ النَّاسُ عَلَى أَمْوَالِهِمْ وَأَنْفُسِهِمْ وَالْمُسْلِمُ مَنْ سَلِمَ النَّاسُ مِنْ لِسَانِهِ وَيَدِهِ وَالْمُجَاهِدُ مَنْ جَاهَدَ نَفْسَهُ فِي طَاعَةِ اللَّهِ وَالْمُهَاجِرُ مَنْ هَجَرَ الْخَطَايَا وَالذَّنُوبَ ‏","","",""],[22834,22834,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏أَنَّ ‏ ‏أَبَا عَلِيٍّ الْهَمْدَانِيَّ ‏ ‏أَخْبَرَهُ ‏ ‏أَنَّهُ رَأَى ‏ ‏فَضَالَةَ بْنَ عُبَيْدٍ ‏ ‏أَمَرَ بِقُبُورِ الْمُسْلِمِينَ فَسُوِّيَتْ بِأَرْضِ ‏ ‏الرُّومِ ‏ ‏وَقَالَ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏سَوُّوا قُبُورَكُمْ بِالْأَرْضِ ‏","","",""],[22835,22835,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏أَنَّهُمْ ‏ ‏كَانُوا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةٍ قَالَ وَفِينَا مَمْلُوكِينَ فَلَا يَقْسِمُ لَهُمْ ‏","","",""],[22836,22836,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْوَلِيدِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏سُفْيَانُ ‏ ‏وَمُحَمَّدُ بْنُ كَثِيرٍ ‏ ‏أَخُو ‏ ‏سُلَيْمَانَ بْنِ كَثِيرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏أَنَّهُمْ ‏ ‏كَانُوا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزَاةٍ قَالَ وَفِينَا مَمْلُوكِينَ فَلَا يَقْسِمُ لَهُمْ ‏","","",""],[22837,22837,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏وَيُونُسُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏قَالَ ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ أَبُو شُجَاعٍ ‏ ‏وَقَالَ ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ سُوَيْدٍ أَبِي شُجَاعٍ الْحِمْيَرِيِّ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ أَبِي عِمْرَانَ ‏ ‏قَالَ ‏ ‏يُونُسُ ‏ ‏الْمَعَافِرِيِّ ‏ ‏عَنْ ‏ ‏حَنَشٍ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏اشْتَرَيْتُ ‏ ‏قِلَادَةً ‏ ‏يَوْمَ فَتْحِ ‏ ‏خَيْبَرَ ‏ ‏بِاثْنَيْ عَشَرَ دِينَارًا فِيهَا ذَهَبٌ وَخَرَزٌ فَفَصَّلْتُهَا فَوَجَدْتُ فِيهَا أَكْثَرَ مِنْ اثْنَيْ عَشَرَ دِينَارًا فَذَكَرْتُ ذَلِكَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لَا تُبَاعُ حَتَّى تُفَصَّلَ ‏","","",""],[22838,22838,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏ابْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَزِيدُ بْنُ حَبِيبٍ ‏ ‏عَنْ ‏ ‏أَبِي مَرْزُوقٍ ‏ ‏مَوْلَى ‏ ‏تُجِيبَ ‏ ‏عَنْ ‏ ‏حَنَشٍ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدِ بْنِ نَافِذٍ الْأَنْصَارِيِّ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي يَوْمٍ كَانَ يَصُومُهُ قَالَ ‏ ‏فَدَعَا بِمَاءٍ فَشَرِبَ فَقُلْنَا لَهُ وَاللَّهِ يَا رَسُولَ اللَّهِ إِنْ كَانَ هَذَا الْيَوْمُ كُنْتَ تَصُومُهُ قَالَ أَجَلْ وَلَكِنِّي قِئْتُ ‏","","",""],[22839,22839,"","","‏ ‏حَدَّثَنَا ‏ ‏يَعْمَرُ بْنُ بِشْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو هَانِئٍ الْخَوْلَانِيُّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَالِكٍ الْجَنْبِيِّ ‏ ‏أَنَّ ‏ ‏فَضَالَةَ بْنَ عُبَيْدٍ ‏ ‏وَعُبَادَةَ بْنَ الصَّامِتِ ‏ ‏حَدَّثَاهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ يَوْمُ الْقِيَامَةِ وَفَرَغَ اللَّهُ تَعَالَى مِنْ قَضَاءِ الْخَلْقِ فَيَبْقَى رَجُلَانِ فَيُؤْمَرُ بِهِمَا إِلَى النَّارِ فَيَلْتَفِتُ أَحَدُهُمَا فَيَقُولُ الْجَبَّارُ تَبَارَكَ اسْمُهُ رُدُّوهُ فَيَرُدُّوهُ فَيُقَالُ لَهُ لِمَ الْتَفَتَّ ‏ ‏يَعْنِي فَيَقُولُ قَدْ كُنْتُ أَرْجُو أَنْ تُدْخِلَنِي الْجَنَّةَ ‏ ‏قَالَ فَيُؤْمَرُ بِهِ إِلَى الْجَنَّةِ فَيَقُولُ لَقَدْ أَعْطَانِي رَبِّي عَزَّ وَجَلَّ حَتَّى لَوْ أَنِّي أَطْعَمْتُ أَهْلَ الْجَنَّةِ مَا نَقَصَ ذَلِكَ مِمَّا عِنْدِي شَيْئًا قَالَا وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا ذَكَرَهُ يُرَى السُّرُورُ فِي وَجْهِهِ ‏","","",""],[22840,22840,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏أَبُو هَانِئٍ الْخَوْلَانِيُّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَمْرَو بْنَ مَالِكٍ الْجَنْبِيَّ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏فَضَالَةَ بْنَ عُبَيْدٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏الْمُجَاهِدُ مَنْ جَاهَدَ نَفْسَهُ فِي سَبِيلِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[22841,22841,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ غَيْلَانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْمُفَضَّلُ بْنُ فَضَالَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ أَبِي حَبِيبٍ ‏ ‏أَنَّهُ أَخْبَرَهُ عَنْ ‏ ‏أَبِي مَرْزُوقٍ ‏ ‏عَنْ ‏ ‏حَنَشٍ الصَّنْعَانِيِّ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏صَائِمًا فَقَاءَ فَأَفْطَرَ ‏","","",""],[22842,22842,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏رِشْدِينُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ أَبِي هَانِئٍ الْخَوْلَانِيِّ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فِي حَجَّةِ الْوَدَاعِ أَلَا أُخْبِرُكُمْ مَنْ ‏ ‏الْمُسْلِمُ مَنْ سَلِمَ الْمُسْلِمُونَ مِنْ لِسَانِهِ وَيَدِهِ وَالْمُؤْمِنُ مَنْ أَمِنَهُ النَّاسُ عَلَى أَمْوَالِهِمْ وَأَنْفُسِهِمْ وَالْمُهَاجِرُ مَنْ هَجَرَ الْخَطَايَا وَالذَّنُوبَ وَالْمُجَاهِدُ مَنْ جَاهَدَ نَفْسَهُ فِي طَاعَةِ اللَّهِ عَزَّ وَجَلَّ ‏","","",""],[22843,22843,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ أَبِي جَعْفَرٍ ‏ ‏عَنِ ‏ ‏الْجُلَاحِ أَبِي كَثِيرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَنَشٌ الصَّنْعَانِيُّ ‏ ‏عَنْ ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏خَيْبَرَ ‏ ‏نُبَايِعُ ‏ ‏الْيَهُودَ ‏ ‏الْأُوقِيَّةَ الذَّهَبَ بِالدِّينَارَيْنِ وَالثَّلَاثَةِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَبِيعُوا الذَّهَبَ بِالذَّهَبِ إِلَّا وَزْنًا بِوَزْنٍ ‏","","",""],[22844,22844,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏أَنَّ رَجُلًا مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَحَلَ إِلَى ‏ ‏فَضَالَةَ بْنِ عُبَيْدٍ ‏ ‏وَهُوَ ‏ ‏بِمِصْرَ ‏ ‏فَقَدِمَ عَلَيْهِ وَهُوَ يَمُدُّ نَاقَةً لَهُ فَقَالَ إِنِّي لَمْ آتِكَ زَائِرًا إِنَّمَا أَتَيْتُكَ لِحَدِيثٍ بَلَغَنِي عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجَوْتُ أَنْ يَكُونَ عِنْدَكَ مِنْهُ عِلْمٌ فَرَآهُ ‏ ‏شَعِثًا ‏ ‏فَقَالَ مَا لِي أَرَاكَ ‏ ‏شَعِثًا ‏ ‏وَأَنْتَ أَمِيرُ الْبَلَدِ قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَنْهَانَا عَنْ كَثِيرٍ مِنْ ‏ ‏الْإِرْفَاهِ ‏ ‏وَرَآهُ حَافِيًا فَقَالَ مَا لِي أَرَاكَ حَافِيًا قَالَ إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَنَا أَنْ نَحْتَفِيَ أَحْيَانًا ‏","","",""],[22845,22845,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏النَّهَّاسُ بْنُ قَهْمٍ أَبُو الْخَطَّابِ ‏ ‏عَنْ ‏ ‏شَدَّادٍ أَبِي عَمَّارٍ الشَّامِيِّ ‏ ‏قَالَ قَالَ ‏ ‏عَوْفُ بْنُ مَالِكٍ ‏ ‏يَا طَاعُونُ خُذْنِي إِلَيْكَ قَالَ فَقَالُوا أَلَيْسَ قَدْ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا عَمَّرَ الْمُسْلِمُ كَانَ خَيْرًا لَهُ قَالَ بَلَى وَلَكِنِّي أَخَافُ سِتًّا إِمَارَةَ السُّفَهَاءِ وَبَيْعَ الْحُكْمِ وَكَثْرَةَ ‏ ‏الشَّرْطِ ‏ ‏وَقَطِيعَةَ الرَّحِمِ وَنَشْئًا يَنْشَئُونَ يَتَّخِذُونَ الْقُرْآنَ مَزَامِيرَ وَسَفْكَ الدَّمِ ‏","","",""],[22846,22846,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏سُفْيَانُ بْنُ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ يُوسُفَ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏اسْتَأْذَنْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقُلْتُ أَدْخُلُ كُلِّي أَوْ بَعْضِي قَالَ ادْخُلْ كُلُّكَ فَدَخَلْتُ عَلَيْهِ وَهُوَ يَتَوَضَّأُ وُضُوءًا ‏ ‏مَكِيثًا ‏ ‏فَقَالَ لِي يَا ‏ ‏عَوْفُ بْنَ مَالِكٍ ‏ ‏أَعْدِدْ ‏ ‏سِتًّا قَبْلَ السَّاعَةِ مَوْتُ نَبِيِّكُمْ خُذْ إِحْدَى ثُمَّ فَتْحُ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏ثُمَّ مَوْتٌ يَأْخُذُكُمْ ‏ ‏تُقْعَصُونَ ‏ ‏فِيهِ كَمَا تُقْعَصُ الْغَنَمُ ثُمَّ تَظْهَرُ الْفِتَنُ وَيَكْثُرُ الْمَالُ حَتَّى يُعْطَى الرَّجُلُ الْوَاحِدُ مِائَةَ دِينَارٍ فَيَسْخَطَهَا ثُمَّ ‏ ‏يَأْتِيكُمْ بَنُو الْأَصْفَرِ تَحْتَ ثَمَانِينَ ‏ ‏غَايَةً ‏ ‏تَحْتَ كُلِّ ‏ ‏غَايَةٍ ‏ ‏اثْنَا عَشَرَ أَلْفًا ‏","","",""],[22847,22847,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الضَّحَّاكُ بْنُ عُثْمَانَ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ بْنِ الْأَشَجِّ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عَوْفُ بْنُ مَالِكٍ ‏ ‏هُوَ ‏ ‏وَذُو الْكَلَاعِ ‏ ‏مَسْجِدَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏فَقَالَ لَهُ ‏ ‏عَوْفٌ ‏ ‏عِنْدَكَ ابْنُ عَمِّكَ فَقَالَ ‏ ‏ذُو الْكَلَاعِ ‏ ‏أَمَا إِنَّهُ مِنْ خَيْرِ ‏ ‏أَوْ مِنْ أَصْلَحِ ‏ ‏النَّاسِ فَقَالَ ‏ ‏عَوْفٌ ‏ ‏أَشْهَدُ لَسَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَقُصُّ إِلَّا أَمِيرٌ أَوْ ‏ ‏مَأْمُورٌ ‏ ‏أَوْ مُتَكَلِّفٌ ‏","","",""],[22848,22848,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏النَّهَّاسُ ‏ ‏عَنْ ‏ ‏شَدَّادٍ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏يَا طَاعُونُ خُذْنِي إِلَيْكَ قَالُوا لِمَ تَقُولُ هَذَا أَلَيْسَ سَمِعْتَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْمُؤْمِنَ لَا يَزِيدُهُ طُولُ الْعُمُرِ إِلَّا خَيْرًا قَالَ بَلَى ‏ ‏فَذَكَرَ مِثْلَ حَدِيثِ ‏ ‏وَكِيعٍ ‏","","",""],[22849,22849,"","","‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَزْهَرَ يَعْنِي ابْنَ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ذِي الْكَلَاعِ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏الْقُصَّاصُ ثَلَاثَةٌ أَمِيرٌ أَوْ ‏ ‏مَأْمُورٌ ‏ ‏أَوْ ‏ ‏مُخْتَالٌ ‏","","",""],[22850,22850,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ عُبَيْدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏جُبَيْرُ بْنُ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏عَوْفٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى مَيِّتٍ فَفَهِمْتُ مِنْ صَلَاتِهِ عَلَيْهِ اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ وَعَافِهِ وَاعْفُ عَنْهُ وَأَكْرِمْ ‏ ‏نُزُلَهُ ‏ ‏وَوَسِّعْ ‏ ‏مُدْخَلَهُ ‏ ‏وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ وَنَقِّهِ مِنْ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنْ ‏ ‏الدَّنَسِ ‏ ‏وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ وَزَوْجَةً خَيْرًا مِنْ زَوْجِهِ وَأَدْخِلْهُ الْجَنَّةَ وَنَجِّهِ مِنْ النَّارِ وَقِهِ عَذَابَ الْقَبْرِ ‏","","",""],[22851,22851,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ الْحَنَفِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْحَمِيدِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏صَالِحِ بْنِ أَبِي عَرِيبٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَعَهُ الْعَصَا وَفِي ‏ ‏الْمَسْجِدِ ‏ ‏أَقْنَاءٌ ‏ ‏مُعَلَّقَةٌ فِيهَا ‏ ‏قِنْوٌ ‏ ‏فِيهِ ‏ ‏حَشَفٌ ‏ ‏فَغَمَزَ ‏ ‏الْقِنْوَ ‏ ‏بِالْعَصَا الَّتِي فِي يَدِهِ قَالَ ‏ ‏لَوْ شَاءَ رَبُّ هَذِهِ الصَّدَقَةِ تَصَدَّقَ بِأَطْيَبَ مِنْهَا إِنَّ رَبَّ هَذِهِ الصَّدَقَةِ لَيَأْكُلُ ‏ ‏الْحَشَفَ ‏ ‏يَوْمَ الْقِيَامَةِ قَالَ ثُمَّ أَقْبَلَ عَلَيْنَا فَقَالَ أَمَا وَاللَّهِ يَا أَهْلَ ‏ ‏الْمَدِينَةِ ‏ ‏لَتَدَعُنَّهَا ‏ ‏أَرْبَعِينَ عَامًا ‏ ‏لِلْعَوَافِي ‏ ‏قَالَ ‏ ‏فَقُلْتُ اللَّهُ أَعْلَمُ قَالَ ‏ ‏يَعْنِي الطَّيْرَ وَالسِّبَاعَ قَالَ وَكُنَّا نَقُولُ إِنَّ هَذَا لَلَّذِي تُسَمِّيهِ ‏ ‏الْعَجَمُ ‏ ‏هِيَ الْكَرَاكِيُّ ‏","","",""],[22852,22852,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي الْمَلِيحِ الْهُذَلِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏زِيَادُ بْنُ أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏أَنَّهُ ‏ ‏كَانَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ فَسَارَ بِهِمْ يَوْمَهُمْ أَجْمَعَ لَا يَحُلُّ لَهُمْ عُقْدَةً وَلَيْلَتَهُ جَمْعَاءَ لَا يَحُلُّ عُقْدَةً إِلَّا لِصَلَاةٍ حَتَّى نَزَلُوا أَوْسَطَ اللَّيْلِ قَالَ فَرَقَبَ رَجُلٌ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ وَضَعَ رَحْلَهُ قَالَ فَانْتَهَيْتُ إِلَيْهِ فَنَظَرْتُ فَلَمْ أَرَ أَحَدًا إِلَّا نَائِمًا وَلَا بَعِيرًا إِلَّا وَاضِعًا جِرَانَهُ نَائِمًا قَالَ فَتَطَاوَلْتُ فَنَظَرْتُ حَيْثُ وَضَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَحْلَهُ فَلَمْ أَرَهُ فِي مَكَانِهِ فَخَرَجْتُ ‏ ‏أَتَخَطَّى الرِّحَالَ حَتَّى خَرَجْتُ إِلَى النَّاسِ ثُمَّ مَضَيْتُ عَلَى وَجْهِي فِي سَوَادِ اللَّيْلِ فَسَمِعْتُ جَرَسًا فَانْتَهَيْتُ إِلَيْهِ فَإِذَا أَنَا ‏ ‏بِمُعَاذِ بْنِ جَبَلٍ ‏ ‏وَالْأَشْعَرِيِّ ‏ ‏فَانْتَهَيْتُ إِلَيْهِمَا فَقُلْتُ أَيْنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا ‏ ‏هَزِيزٌ ‏ ‏كَهَزِيزِ ‏ ‏الرَّحَا ‏ ‏فَقُلْتُ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ هَذَا الصَّوْتِ قَالَا اقْعُدْ اسْكُتْ فَمَضَى قَلِيلًا فَأَقْبَلَ حَتَّى انْتَهَى إِلَيْنَا فَقُمْنَا إِلَيْهِ فَقُلْنَا يَا رَسُولَ اللَّهِ فَزِعْنَا إِذْ لَمْ نَرَكَ وَاتَّبَعْنَا أَثَرَكَ فَقَالَ إِنَّهُ ‏ ‏أَتَانِي آتٍ مِنْ رَبِّي عَزَّ وَجَلَّ فَخَيَّرَنِي بَيْنَ أَنْ يَدْخُلَ نِصْفُ أُمَّتِي الْجَنَّةَ وَبَيْنَ الشَّفَاعَةِ فَاخْتَرْتُ الشَّفَاعَةَ فَقُلْنَا نُذَكِّرُكَ اللَّهَ وَالصُّحْبَةَ ‏ ‏إِلَّا جَعَلْتَنَا مِنْ أَهْلِ شَفَاعَتِكَ قَالَ أَنْتُمْ مِنْهُمْ ثُمَّ مَضَيْنَا فَيَجِيءُ الرَّجُلُ وَالرَّجُلَانِ فَيُخْبِرُهُمْ بِالَّذِي أَخْبَرَنَا بِهِ فَيُذَكِّرُونَهُ اللَّهَ وَالصُّحْبَةَ إِلَّا جَعَلَهُمْ مِنْ أَهْلِ شَفَاعَتِهِ فَيَقُولُ فَإِنَّكُمْ مِنْهُمْ حَتَّى انْتَهَى النَّاسُ فَأَضَبُّوا عَلَيْهِ وَقَالُوا اجْعَلْنَا مِنْهُمْ قَالَ فَإِنِّي أُشْهِدُكُمْ أَنَّهَا لِمَنْ مَاتَ مِنْ أُمَّتِي لَا يُشْرِكُ بِاللَّهِ شَيْئًا ‏","","",""],[22853,22853,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ إِسْحَاقَ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏ابْنُ مُبَارَكٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏سَعِيدُ بْنُ أَبِي أَيُّوبَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ أَبِي حَبِيبٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ لَقِيطٍ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ هِدْمٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏غَزَوْنَا وَعَلَيْنَا ‏ ‏عَمْرُو بْنُ الْعَاصِ ‏ ‏فَأَصَابَتْنَا ‏ ‏مَخْمَصَةٌ ‏ ‏فَمَرُّوا عَلَى قَوْمٍ قَدْ نَحَرُوا ‏ ‏جَزُورًا ‏ ‏فَقُلْتُ أُعَالِجُهَا لَكُمْ عَلَى أَنْ تُطْعِمُونِي مِنْهَا شَيْئًا ‏ ‏وَقَالَ ‏ ‏إِبْرَاهِيمُ ‏ ‏فَتُطْعِمُونِي مِنْهَا ‏ ‏فَعَالَجْتُهَا ثُمَّ أَخَذْتُ الَّذِي أَعْطَوْنِي فَأَتَيْتُ بِهِ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏فَأَبَى أَنْ يَأْكُلَهُ ثُمَّ أَتَيْتُ بِهِ ‏ ‏أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ ‏ ‏فَقَالَ مِثْلَ مَا قَالَ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏وَأَبَى ‏ ‏أَنْ يَأْكُلَ ثُمَّ إِنِّي بُعِثْتُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ ذَاكَ فِي فَتْحِ ‏ ‏مَكَّةَ ‏ ‏فَقَالَ ‏ ‏أَنْتَ صَاحِبُ ‏ ‏الْجَزُورِ ‏ ‏فَقُلْتُ نَعَمْ يَا رَسُولَ اللَّهِ لَمْ يَزِدْنِي عَلَى ذَلِكَ ‏","","",""],[22854,22854,"","","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عَمْرٍو الرُّقِّيُّ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ رَاشِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ زَيْدِ بْنِ الْخَطَّابِ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِتَبُوكَ ‏ ‏مِنْ آخِرِ ‏ ‏السَّحَرِ ‏ ‏وَهُوَ فِي ‏ ‏فُسْطَاطٍ ‏ ‏أَوْ قَالَ ‏ ‏قُبَّةٍ ‏ ‏مِنْ ‏ ‏أَدَمٍ ‏ ‏قَالَ فَسَأَلْتُ ثُمَّ اسْتَأْذَنْتُ فَقُلْتُ أَدْخُلُ فَقَالَ ‏ ‏ادْخُلْ قُلْتُ كُلِّي قَالَ كُلُّكَ قَالَ فَدَخَلْتُ وَإِذَا هُوَ يَتَوَضَّأُ وُضُوءًا ‏ ‏مَكِيثًا ‏","","",""],[22855,22855,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ سَوَّارٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏لَيْثٌ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ قَيْسٍ الْكِنْدِيِّ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَاصِمَ بْنَ حُمَيْدٍ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَوْفَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏قُمْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَدَأَ ‏ ‏فَاسْتَاكَ ثُمَّ تَوَضَّأَ ثُمَّ قَامَ ‏ ‏يُصَلِّي وَقُمْتُ مَعَهُ فَبَدَأَ فَاسْتَفْتَحَ ‏ ‏الْبَقَرَةَ ‏ ‏لَا يَمُرُّ بِآيَةِ رَحْمَةٍ إِلَّا وَقَفَ فَسَأَلَ وَلَا يَمُرُّ بِآيَةِ عَذَابٍ إِلَّا وَقَفَ يَتَعَوَّذُ ثُمَّ رَكَعَ فَمَكَثَ رَاكِعًا بِقَدْرِ قِيَامِهِ يَقُولُ فِي رُكُوعِهِ سُبْحَانَ ذِي الْجَبَرُوتِ وَالْمَلَكُوتِ وَالْكِبْرِيَاءِ وَالْعَظَمَةِ ثُمَّ قَرَأَ ‏ ‏آلَ ‏ ‏عِمْرَانَ ‏ ‏ثُمَّ سُورَةً فَفَعَلَ مِثْلَ ذَلِكَ ‏","","",""],[22856,22856,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَبْدُ اللَّهِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ يَزِيدَ بْنِ جَابِرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏زُرَيْقٌ ‏ ‏مَوْلَى ‏ ‏بَنِي فَزَارَةَ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ قَرَظَةَ ‏ ‏وَكَانَ ابْنَ عَمِّ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَوْفَ بْنَ مَالِكٍ ‏ ‏يَقولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏خِيَارُ أَئِمَّتِكُمْ مَنْ تُحِبُّونَهُمْ وَيُحِبُّونَكُمْ وَتُصَلُّونَ عَلَيْهِمْ وَيُصَلُّونَ عَلَيْكُمْ وَشِرَارُ أَئِمَّتِكُمْ الَّذِينَ تُبْغِضُونَهُمْ وَيُبْغِضُونَكُمْ وَتَلْعَنُونَهُمْ وَيَلْعَنُونَكُمْ قُلْنَا يَا رَسُولَ اللَّهِ أَفَلَا ‏ ‏نُنَابِذُهُمْ ‏ ‏عِنْدَ ذَلِكَ قَالَ لَا مَا أَقَامُوا لَكُمْ الصَّلَاةَ أَلَا وَمَنْ وُلِّيَ عَلَيْهِ أَمِيرٌ وَالٍ فَرَآهُ يَأْتِي شَيْئًا مِنْ مَعْصِيَةِ اللَّهِ فَلْيُنْكِرْ مَا يَأْتِي مِنْ مَعْصِيَةِ اللَّهِ وَلَا يَنْزِعَنَّ يَدًا مِنْ طَاعَةٍ ‏","","",""],[22857,22857,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَامَ فِي أَصْحَابِهِ فَقَالَ ‏ ‏الْفَقْرَ تَخَافُونَ أَوْ ‏ ‏الْعَوَزَ ‏ ‏أَوَتُهِمُّكُمْ الدُّنْيَا فَإِنَّ اللَّهَ فَاتِحٌ لَكُمْ أَرْضَ ‏ ‏فَارِسَ ‏ ‏وَالرُّومِ ‏ ‏وَتُصَبُّ عَلَيْكُمْ الدُّنْيَا صَبًّا حَتَّى لَا ‏ ‏يُزِيغُكُمْ ‏ ‏بَعْدِي إِنْ أَزَاغَكُمْ إِلَّا هِيَ ‏","","",""],[22858,22858,"","","‏ ‏حَدَّثَنَا ‏ ‏حَيْوَةُ بْنُ شُرَيْحٍ ‏ ‏وَإِبْرَاهِيمُ بْنُ أَبِي الْعَبَّاسِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏بَحِيرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏سَيْفٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ حَدَّثَهُمْ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى بَيْنَ رَجُلَيْنِ فَقَالَ الْمَقْضِيُّ عَلَيْهِ لَمَّا أَدْبَرَ ‏ ‏حَسْبِيَ ‏ ‏اللَّهُ وَنِعْمَ الْوَكِيلُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُدُّوا عَلَيَّ الرَّجُلَ فَقَالَ مَا قُلْتَ قَالَ قُلْتُ ‏ ‏حَسْبِيَ اللَّهُ وَنِعْمَ الْوَكِيلُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ يَلُومُ عَلَى ‏ ‏الْعَجْزِ ‏ ‏وَلَكِنْ عَلَيْكَ ‏ ‏بِالْكَيْسِ ‏ ‏فَإِذَا غَلَبَكَ أَمْرٌ فَقُلْ ‏ ‏حَسْبِيَ اللَّهُ وَنِعْمَ الْوَكِيلُ ‏","","",""],[22859,22859,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏انْطَلَقَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمًا وَأَنَا مَعَهُ حَتَّى دَخَلْنَا كَنِيسَةَ ‏ ‏الْيَهُودِ ‏ ‏بِالْمَدِينَةِ ‏ ‏يَوْمَ عِيدٍ لَهُمْ فَكَرِهُوا دُخُولَنَا عَلَيْهِمْ فَقَالَ لَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا مَعْشَرَ ‏ ‏الْيَهُودِ ‏ ‏أَرُونِي اثْنَيْ عَشَرَ رَجُلًا يَشْهَدُونَ أَنَّهُ لَا إِلَهَ إِلَّا اللَّهُ وَأَنَّ ‏ ‏مُحَمَّدًا ‏ ‏رَسُولُ اللَّهِ يُحْبِطْ اللَّهُ عَنْ كُلِّ يَهُودِيٍّ تَحْتَ ‏ ‏أَدِيمِ ‏ ‏السَّمَاءِ الْغَضَبَ الَّذِي غَضِبَ عَلَيْهِ قَالَ فَأَسْكَتُوا مَا أَجَابَهُ مِنْهُمْ أَحَدٌ ثُمَّ رَدَّ عَلَيْهِمْ فَلَمْ يُجِبْهُ أَحَدٌ ثُمَّ ثَلَّثَ فَلَمْ يُجِبْهُ أَحَدٌ فَقَالَ أَبَيْتُمْ فَوَاللَّهِ إِنِّي لَأَنَا ‏ ‏الْحَاشِرُ ‏ ‏وَأَنَا ‏ ‏الْعَاقِبُ ‏ ‏وَأَنَا النَّبِيُّ ‏ ‏الْمُصْطَفَى ‏ ‏آمَنْتُمْ أَوْ كَذَّبْتُمْ ثُمَّ انْصَرَفَ وَأَنَا مَعَهُ حَتَّى إِذَا كِدْنَا أَنْ نَخْرُجَ نَادَى رَجُلٌ مِنْ خَلْفِنَا كَمَا أَنْتَ يَا ‏ ‏مُحَمَّدُ ‏ ‏قَالَ فَأَقْبَلَ فَقَالَ ذَلِكَ الرَّجُلُ أَيَّ رَجُلٍ تَعْلَمُونَ فِيكُمْ يَا مَعْشَرَ ‏ ‏الْيَهُودِ ‏ ‏قَالُوا وَاللَّهِ مَا نَعْلَمُ أَنَّهُ كَانَ فِينَا رَجُلٌ أَعْلَمُ بِكِتَابِ اللَّهِ مِنْكَ وَلَا أَفْقَهُ مِنْكَ وَلَا مِنْ أَبِيكَ قَبْلَكَ وَلَا مِنْ جَدِّكَ قَبْلَ أَبِيكَ قَالَ فَإِنِّي أَشْهَدُ لَهُ بِاللَّهِ أَنَّهُ نَبِيُّ اللَّهِ الَّذِي تَجِدُونَهُ فِي التَّوْرَاةِ قَالُوا كَذَبْتَ ثُمَّ رَدُّوا عَلَيْهِ قَوْلَهُ وَقَالُوا فِيهِ شَرًّا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَذَبْتُمْ لَنْ يُقْبَلَ قَوْلُكُمْ أَمَّا ‏ ‏آنِفًا ‏ ‏فَتُثْنُونَ عَلَيْهِ مِنْ الْخَيْرِ مَا أَثْنَيْتُمْ وَلَمَّا آمَنَ كَذَّبْتُمُوهُ وَقُلْتُمْ فِيهِ مَا قُلْتُمْ فَلَنْ يُقْبَلَ قَوْلُكُمْ قَالَ فَخَرَجْنَا وَنَحْنُ ثَلَاثَةٌ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَا ‏ ‏وَعَبْدُ اللَّهِ بْنُ سَلَامٍ ‏ ‏وَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ فِيهِ ‏ { ‏قُلْ أَرَأَيْتُمْ إِنْ كَانَ مِنْ عِنْدِ اللَّهِ وَكَفَرْتُمْ بِهِ وَشَهِدَ شَاهِدٌ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏عَلَى مِثْلِهِ فَآمَنَ وَاسْتَكْبَرْتُمْ إِنَّ اللَّهَ لَا يَهْدِي الْقَوْمَ الظَّالِمِينَ ‏}","","",""],[22860,22860,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَلَّمْتُ عَلَيْهِ فَقَالَ ‏ ‏عَوْفٌ ‏ ‏فَقُلْتُ نَعَمْ فَقَالَ ادْخُلْ قَالَ قُلْتُ كُلِّي أَوْ بَعْضِي قَالَ بَلْ كُلُّكَ قَالَ يَا ‏ ‏عَوْفُ ‏ ‏اعْدُدْ سِتًّا بَيْنَ يَدَيْ السَّاعَةِ أَوَّلُهُنَّ مَوْتِي قَالَ فَاسْتَبْكَيْتُ حَتَّى جَعَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسْكِتُنِي قَالَ قُلْتُ إِحْدَى وَالثَّانِيَةُ فَتْحُ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏قُلْتُ اثْنَيْنِ وَالثَّالِثَةُ ‏ ‏مُوتَانٌ يَكُونُ فِي أُمَّتِي يَأْخُذُهُمْ مِثْلَ قُعَاصِ الْغَنَمِ قَالَ ثَلَاثًا وَالرَّابِعَةُ فِتْنَةٌ تَكُونُ فِي أُمَّتِي وَعَظَّمَهَا قُلْ أَرْبَعًا وَالْخَامِسَةُ يَفِيضُ الْمَالُ فِيكُمْ حَتَّى إِنَّ الرَّجُلَ ‏ ‏لَيُعْطَى الْمِائَةَ دِينَارٍ فَيَتَسَخَّطُهَا قُلْ خَمْسًا وَالسَّادِسَةُ هُدْنَةٌ تَكُونُ بَيْنَكُمْ وَبَيْنَ ‏ ‏بَنِي الْأَصْفَرِ ‏ ‏فَيَسِيرُونَ إِلَيْكُمْ عَلَى ثَمَانِينَ غَايَةً قُلْتُ وَمَا الْغَايَةُ قَالَ الرَّايَةُ تَحْتَ كُلِّ رَايَةٍ اثْنَا عَشَرَ أَلْفًا فُسْطَاطُ الْمُسْلِمِينَ يَوْمَئِذٍ فِي أَرْضٍ يُقَالُ لَهَا ‏ ‏الْغُوطَةُ ‏ ‏فِي مَدِينَةٍ يُقَالُ لَهَا ‏ ‏دِمَشْقُ ‏","","",""],[22861,22861,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا جَاءَ فَيْءٌ قَسَمَهُ مِنْ يَوْمِهِ فَأَعْطَى الْآهِلَ حَظَّيْنِ وَأَعْطَى ‏ ‏الْعَزَبَ ‏ ‏حَظًّا وَاحِدًا فَدُعِينَا وَكُنْتُ ‏ ‏أُدْعَى قَبْلَ ‏ ‏عَمَّارِ بْنِ يَاسِرٍ ‏ ‏فَدُعِيتُ فَأَعْطَانِي حَظَّيْنِ وَكَانَ لِي أَهْلٌ ثُمَّ دَعَا ‏ ‏بِعَمَّارِ بْنِ يَاسِرٍ ‏ ‏فَأُعْطِيَ حَظًّا وَاحِدًا فَبَقِيَتْ قِطْعَةُ سِلْسِلَةٍ مِنْ ذَهَبٍ فَجَعَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْفَعُهَا بِطَرَفِ عَصَاهُ ثُمَّ رَفَعَهَا ‏ ‏وَهُوَ يَقُولُ كَيْفَ أَنْتُمْ يَوْمَ يَكْثُرُ لَكُمْ مِنْ هَذَا ‏","","",""],[22862,22862,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَفْوَانُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏جُبَيْرٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏غَزَوْنَا غَزْوَةً إِلَى طَرَفِ ‏ ‏الشَّامِ ‏ ‏فَأُمِّرَ عَلَيْنَا ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏قَالَ فَانْضَمَّ إِلَيْنَا رَجُلٌ مِنْ أَمْدَادِ ‏ ‏حِمْيَرَ ‏ ‏فَأَوَى إِلَى رَحْلِنَا لَيْسَ مَعَهُ شَيْءٌ إِلَّا سَيْفٌ لَيْسَ مَعَهُ سِلَاحٌ غَيْرَهُ فَنَحَرَ رَجُلٌ مِنْ الْمُسْلِمِينَ ‏ ‏جَزُورًا ‏ ‏فَلَمْ يَزَلْ يَحْتَلْ حَتَّى أَخَذَ مِنْ جِلْدِهِ كَهَيْئَةِ ‏ ‏الْمِجَنِّ ‏ ‏حَتَّى بَسَطَهُ عَلَى الْأَرْضِ ثُمَّ وَقَدَ عَلَيْهِ حَتَّى جَفَّ فَجَعَلَ لَهُ مُمْسِكًا كَهَيْئَةِ التُّرْسِ فَقُضِيَ أَنْ ‏ ‏لَقِينَا ‏ ‏عَدُوَّنَا فِيهِمْ أَخْلَاطٌ مِنْ ‏ ‏الرُّومِ ‏ ‏وَالْعَرَبِ ‏ ‏مِنْ ‏ ‏قُضَاعَةَ ‏ ‏فَقَاتَلُونَا قِتَالًا شَدِيدًا وَفِي الْقَوْمِ رَجُلٌ مِنْ ‏ ‏الرُّومِ ‏ ‏عَلَى فَرَسٍ لَهُ أَشْقَرَ وَسَرْجٍ مُذَهَّبٍ وَمِنْطَقَةٍ مُلَطَّخَةٍ ذَهَبًا وَسَيْفٌ مِثْلُ ذَلِكَ فَجَعَلَ يَحْمِلُ عَلَى الْقَوْمِ ‏ ‏وَيُغْرِي بِهِمْ فَلَمْ يَزَلْ ذَلِكَ ‏ ‏الْمَدَدِيُّ يَحْتَالُ لِذَلِكَ الرُّومِيِّ حَتَّى مَرَّ بِهِ ‏ ‏فَاسْتَقْفَاهُ ‏ ‏فَضَرَبَ ‏ ‏عُرْقُوبَ ‏ ‏فَرَسِهِ بِالسَّيْفِ فَوَقَعَ ثُمَّ أَتْبَعَهُ ضَرْبًا بِالسَّيْفِ حَتَّى قَتَلَهُ فَلَمَّا فَتَحَ اللَّهُ الْفَتْحَ أَقْبَلَ يَسْأَلُ ‏ ‏لِلسَّلَبِ ‏ ‏وَقَدْ شَهِدَ لَهُ النَّاسُ بِأَنَّهُ قَاتِلُهُ فَأَعْطَاهُ ‏ ‏خَالِدٌ ‏ ‏بَعْضَ ‏ ‏سَلَبِهِ ‏ ‏وَأَمْسَكَ سَائِرَهُ فَلَمَّا رَجَعَ إِلَى رَحْلِ ‏ ‏عَوْفٍ ‏ ‏ذَكَرَهُ فَقَالَ لَهُ ‏ ‏عَوْفٌ ‏ ‏ارْجِعْ إِلَيْهِ فَلْيُعْطِكَ مَا بَقِيَ فَرَجَعَ إِلَيْهِ فَأَبَى عَلَيْهِ فَمَشَى ‏ ‏عَوْفٌ ‏ ‏حَتَّى أَتَى ‏ ‏خَالِدًا ‏ ‏فَقَالَ أَمَا تَعْلَمُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى ‏ ‏بِالسَّلَبِ ‏ ‏لِلْقَاتِلِ قَالَ بَلَى قَالَ فَمَا يَمْنَعُكَ أَنْ تَدْفَعَ إِلَيْهِ سَلَبَ قَتِيلِهِ قَالَ ‏ ‏خَالِدٌ ‏ ‏اسْتَكْثَرْتُهُ لَهُ قَالَ ‏ ‏عَوْفٌ ‏ ‏لَئِنْ رَأَيْتُ وَجْهَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَأَذْكُرَنَّ ذَلِكَ لَهُ فَلَمَّا قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏بَعَثَهُ ‏ ‏عَوْفٌ ‏ ‏فَاسْتَعْدَى إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا ‏ ‏خَالِدًا ‏ ‏وَعَوْفٌ ‏ ‏قَاعِدٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يَمْنَعُكَ يَا ‏ ‏خَالِدُ ‏ ‏أَنْ تَدْفَعَ إِلَى هَذَا ‏ ‏سَلَبَ ‏ ‏قَتِيلِهِ قَالَ اسْتَكْثَرْتُهُ لَهُ يَا رَسُولَ اللَّهِ فَقَالَ ادْفَعْهُ إِلَيْهِ قَالَ فَمَرَّ ‏ ‏بِعَوْفٍ ‏ ‏فَجَرَّ ‏ ‏عَوْفٌ ‏ ‏بِرِدَائِهِ فَقَالَ ‏ ‏لِيَجْزِي لَكَ مَا ذَكَرْتُ لَكَ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَمِعَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاسْتُغْضِبَ فَقَالَ لَا تُعْطِهِ يَا ‏ ‏خَالِدُ ‏ ‏هَلْ أَنْتُمْ تَارِكِي أُمَرَائِي إِنَّمَا مَثَلُكُمْ وَمَثَلُهُمْ كَمَثَلِ رَجُلٍ اسْتُرْعِيَ إِبِلًا أَوْ غَنَمًا فَرَعَاهَا ثُمَّ تَخَيَّرَ سَقْيَهَا فَأَوْرَدَهَا حَوْضًا فَشَرَعَتْ فِيهِ فَشَرِبَتْ صَفْوَةَ الْمَاءِ وَتَرَكَتْ كَدَرَهُ فَصَفْوُهُ لَكُمْ وَكَدَرُهُ عَلَيْهِمْ ‏","","",""],[22863,22863,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْمُغِيرَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَفْوَانُ بْنُ عَمْرٍو ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏وَخَالِدِ بْنِ الْوَلِيدِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يُخَمِّسْ ‏ ‏السَّلَبَ ‏","","",""],[22864,22864,"","","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ سَوَّارٍ أَبُو الْعَلَاءِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ جَابِرٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَنْ يَجْمَعَ اللَّهُ عَزَّ وَجَلَّ عَلَى هَذِهِ الْأُمَّةِ سَيْفَيْنِ سَيْفًا مِنْهَا وَسَيْفًا مِنْ عَدُوِّهَا ‏","","",""],[22865,22865,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ بَحْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ حِمْيَرٍ الْحِمْصِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏إِبْرَاهِيمُ بْنُ أَبِي عَبْلَةَ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ الْجُرَشِيِّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جُبَيْرُ بْنُ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏بَيْنَمَا نَحْنُ جُلُوسٌ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ ‏ ‏فَنَظَرَ فِي السَّمَاءِ ثُمَّ قَالَ هَذَا أَوَانُ الْعِلْمِ أَنْ يُرْفَعَ فَقَالَ لَهُ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏يُقَالُ لَهُ ‏ ‏زِيَادُ بْنُ لَبِيدٍ ‏ ‏أَيُرْفَعُ الْعِلْمُ يَا رَسُولَ اللَّهِ وَفِينَا كِتَابُ اللَّهِ وَقَدْ عَلَّمْنَاهُ أَبْنَاءَنَا وَنِسَاءَنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنْ كُنْتُ لَأَظُنُّكَ مِنْ أَفْقَهِ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏ثُمَّ ذَكَرَ ضَلَالَةَ أَهْلِ الْكِتَابَيْنِ وَعِنْدَهُمَا مَا عِنْدَهُمَا مِنْ كِتَابِ اللَّهِ عَزَّ وَجَلَّ ‏ ‏فَلَقِيَ ‏ ‏جُبَيْرُ بْنُ نُفَيْرٍ ‏ ‏شَدَّادَ بْنَ أَوْسٍ ‏ ‏بِالْمُصَلَّى فَحَدَّثَهُ هَذَا الْحَدِيثَ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏فَقَالَ ‏ ‏صَدَقَ ‏ ‏عَوْفٌ ‏ ‏ثُمَّ قَالَ وَهَلْ تَدْرِي مَا رَفْعُ الْعِلْمِ قَالَ قُلْتُ لَا أَدْرِي قَالَ ذَهَابُ أَوْعِيَتِهِ قَالَ وَهَلْ تَدْرِي أَيُّ الْعِلْمِ أَوَّلُ أَنْ يُرْفَعَ قَالَ قُلْتُ لَا أَدْرِي قَالَ الْخُشُوعُ حَتَّى لَا تَكَادُ ‏ ‏تَرَى خَاشِعًا ‏","","",""],[22866,22866,"","","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ أَبِي عَاصِمٍ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏النَّهَّاسُ بْنُ قَهْمٍ ‏ ‏عَنْ ‏ ‏أَبِي عَمَّارٍ شَدَّادٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كُنَّ لَهُ ‏ ‏ثَلَاثُ ‏ ‏بَنَاتٍ أَوْ ثَلَاثُ أَخَوَاتٍ أَوْ بِنْتَانِ أَوْ أُخْتَانِ اتَّقَى اللَّهَ فِيهِنَّ وَأَحْسَنَ إِلَيْهِنَّ حَتَّى ‏ ‏يَبِنَّ ‏ ‏أَوْ يَمُتْنَ ‏ ‏كُنَّ لَهُ حِجَابًا مِنْ النَّارِ ‏","","",""],[22867,22867,"","","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بُكَيْرُ بْنُ الْأَشَجِّ ‏ ‏عَنْ ‏ ‏يَعْقُوبَ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ قَاصَّ مَسْلَمَةَ ‏ ‏حَدَّثَهُ أَنَّ ‏ ‏عَوْفَ بْنَ مَالِكٍ ‏ ‏حَدَّثَهُ قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَقُصُّ إِلَّا أَمِيرٌ أَوْ ‏ ‏مَأْمُورٌ ‏ ‏أَوْ ‏ ‏مُخْتَالٌ ‏","","",""],[22868,22868,"","","‏ ‏حَدَّثَنَا ‏ ‏قُتَيْبَةُ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ لَهِيعَةَ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ حَبِيبٍ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ لَقِيطٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سِتَّةِ نَفَرٍ ‏ ‏أَوْ سَبْعَةٍ أَوْ ثَمَانِيَةٍ ‏ ‏فَقَالَ لَنَا بَايِعُونِي فَقُلْنَا يَا نَبِيَّ اللَّهِ قَدْ بَايَعْنَاكَ قَالَ ‏ ‏بَايِعُونِي فَبَايَعْنَاهُ فَأَخَذَ عَلَيْنَا بِمَا أَخَذَ عَلَى النَّاسِ ثُمَّ أَتْبَعَ ذَلِكَ كَلِمَةً خَفِيَّةً فَقَالَ لَا تَسْأَلُوا النَّاسَ شَيْئًا ‏","","",""],[22869,22869,"","","‏ ‏حَدَّثَنَا ‏ ‏هَارُونُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ وَهْبٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْحَارِثِ ‏ ‏عَنْ ‏ ‏بُكَيْرِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏يَعْقُوبَ ‏ ‏أَخَاهُ ‏ ‏وَابْنَ أَبِي حَفْصَةَ ‏ ‏حَدَّثَاهُ أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ يَزِيدَ قَاصَّ مَسْلَمَةَ ‏ ‏بِالْقُسْطَنْطِينِيَّةِ ‏ ‏حَدَّثَهُمَا عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَا يَقُصُّ عَلَى النَّاسِ إِلَّا أَمِيرٌ أَوْ ‏ ‏مَأْمُورٌ ‏ ‏أَوْ ‏ ‏مُخْتَالٌ ‏","","",""],[22870,22870,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏دَاوُدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏بُسْرِ بْنِ عُبَيْدِ اللَّهِ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏أَبِي إِدْرِيسَ الْخَوْلَانِيِّ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ بِالْمَسْحِ عَلَى الْخُفَّيْنِ فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏ثَلَاثَةُ أَيَّامٍ لِلْمُسَافِرِ وَلَيَالِيهِنَّ وَلِلْمُقِيمِ يَوْمٌ وَلَيْلَةٌ ‏","","",""],[22871,22871,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏يَعْلَى بْنُ عَطَاءٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي ‏ ‏خِدْرٍ ‏ ‏لَهُ فَقُلْتُ أَدْخُلُ فَقَالَ ادْخُلْ قُلْتُ أَكُلِّي قَالَ كُلُّكَ فَلَمَّا جَلَسْتُ قَالَ ‏ ‏امْسِكْ سِتًّا تَكُونُ قَبْلَ السَّاعَةِ أَوَّلُهُنَّ وَفَاةُ نَبِيِّكُمْ قَالَ فَبَكَيْتُ ‏ ‏قَالَ ‏ ‏هُشَيْمٌ ‏ ‏وَلَا أَدْرِي بِأَيِّهَا بَدَأَ ‏ ‏ثُمَّ فَتْحُ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏وَفِتْنَةٌ تَدْخُلُ بَيْتَ كُلِّ شَعَرٍ ‏ ‏وَمَدَرٍ ‏ ‏وَأَنْ يَفِيضَ الْمَالُ فِيكُمْ حَتَّى يُعْطَى الرَّجُلُ مِائَةَ دِينَارٍ فَيَتَسَخَّطَهَا ‏ ‏وَمُوتَانٌ يَكُونُ فِي النَّاسِ ‏ ‏كَقُعَاصِ ‏ ‏الْغَنَمِ قَالَ وَهُدْنَةٌ تَكُونُ بَيْنَكُمْ وَبَيْنَ ‏ ‏بَنِي الْأَصْفَرِ ‏ ‏فَيَغْدِرُونَ بِكُمْ فَيَسِيرُونَ إِلَيْكُمْ فِي ثَمَانِينَ ‏ ‏غَايَةً ‏ ‏وَقَالَ ‏ ‏يَعْلَى ‏ ‏فِي سِتِّينَ ‏ ‏غَايَةً ‏ ‏تَحْتَ كُلِّ ‏ ‏غَايَةٍ ‏ ‏اثْنَا عَشَرَ أَلْفًا ‏","","",""],[22872,22872,"","","‏ ‏حَدَّثَنَا ‏ ‏الْوَلِيدُ بْنُ مُسْلِمٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏صَفْوَانُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏خَرَجْتُ مَعَ مَنْ خَرَجَ مَعَ ‏ ‏زَيْدِ بْنِ حَارِثَةَ ‏ ‏مِنْ الْمُسْلِمِينَ فِي غَزْوَةِ ‏ ‏مُؤْتَةَ ‏ ‏وَرَافَقَنِي ‏ ‏مَدَدِيٌّ ‏ ‏مِنْ ‏ ‏الْيَمَنِ ‏ ‏لَيْسَ مَعَهُ غَيْرُ سَيْفِهِ فَنَحَرَ رَجُلٌ مِنْ الْمُسْلِمِينَ ‏ ‏جَزُورًا ‏ ‏فَسَأَلَهُ ‏ ‏الْمَدَدِيُّ طَائِفَةً مِنْ جِلْدِهِ فَأَعْطَاهُ إِيَّاهُ فَاتَّخَذَهُ كَهَيْئَةِ ‏ ‏الدَّرَقِ ‏ ‏وَمَضَيْنَا فَلَقِينَا جُمُوعَ ‏ ‏الرُّومِ ‏ ‏وَفِيهِمْ رَجُلٌ عَلَى فَرَسٍ لَهُ أَشْقَرَ عَلَيْهِ ‏ ‏سَرْجٌ ‏ ‏مُذَهَّبٌ وَسِلَاحٌ مُذَهَّبٌ فَجَعَلَ الرُّومِيُّ ‏ ‏يُغْرِي بِالْمُسْلِمِينَ وَقَعَدَ لَهُ ‏ ‏الْمَدَدِيُّ خَلْفَ صَخْرَةٍ فَمَرَّ بِهِ الرُّومِيُّ ‏ ‏فَعَرْقَبَ ‏ ‏فَرَسَهُ ‏ ‏فَخَرَّ ‏ ‏وَعَلَاهُ فَقَتَلَهُ وَحَازَ فَرَسَهُ وَسِلَاحَهُ فَلَمَّا فَتَحَ ‏ ‏اللَّهُ لِلْمُسْلِمِينَ بَعَثَ إِلَيْهِ ‏ ‏خَالِدُ بْنُ الْوَلِيدِ ‏ ‏فَأَخَذَ مِنْهُ ‏ ‏السَّلَبَ ‏ ‏قَالَ ‏ ‏عَوْفٌ ‏ ‏فَأَتَيْتُهُ فَقُلْتُ يَا ‏ ‏خَالِدُ ‏ ‏أَمَا عَلِمْتَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَضَى ‏ ‏بِالسَّلَبِ ‏ ‏لِلْقَاتِلِ قَالَ بَلَى وَلَكِنِّي اسْتَكْثَرْتُهُ قُلْتُ لَتَرُدَّنَّهُ إِلَيْهِ أَوْ لَأُعَرِّفَنَّكَهَا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَى أَنْ يَرُدَّ عَلَيْهِ قَالَ ‏ ‏عَوْفٌ ‏ ‏فَاجْتَمَعَا عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَصَصْتُ عَلَيْهِ قِصَّةَ ‏ ‏الْمَدَدِيِّ وَمَا فَعَلَهُ ‏ ‏خَالِدٌ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏خَالِدُ ‏ ‏مَا حَمَلَكَ عَلَى مَا صَنَعْتَ قَالَ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَكْثَرْتُهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏خَالِدُ ‏ ‏رُدَّ عَلَيْهِ مَا أَخَذْتَ مِنْهُ قَالَ ‏ ‏عَوْفٌ ‏ ‏فَقَالَ دُونَكَ يَا ‏ ‏خَالِدُ ‏ ‏أَلَمْ ‏ ‏أَفِ ‏ ‏لَكَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَمَا ذَاكَ فَأَخْبَرْتُهُ فَغَضِبَ رَسُولُ اللَّهِ وَقَالَ يَا ‏ ‏خَالِدُ ‏ ‏لَا تَرُدَّهُ عَلَيْهِ هَلْ أَنْتُمْ تَارِكُو إِلَيَّ ‏ ‏أُمَرَائِي ‏ ‏لَكُمْ صَفْوَةُ أَمْرِهِمْ وَعَلَيْهِمْ كَدَرُهُ ‏ ‏قَالَ ‏ ‏الْوَلِيدُ ‏ ‏سَأَلْتُ ‏ ‏ثَوْرًا ‏ ‏عَنْ هَذَا الْحَدِيثِ ‏ ‏فَحَدَّثَنِي عَنْ ‏ ‏خَالِدِ بْنِ مَعْدَانَ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏نَحْوَهُ ‏","","",""],[22873,22873,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَي بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الْحَمِيدِ يَعْنِي أَبَا جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏صَالِحُ بْنُ أَبِي عَرِيبٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ الْحَضْرَمِيِّ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏خَرَجَ عَلَيْنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ دَخَلَ ‏ ‏وَنَحْنُ فِي الْمَسْجِدِ وَبِيَدِهِ عَصًا وَقَدْ عَلَّقَ رَجُلٌ أَقْنَاءَ ‏ ‏حَشَفٍ ‏ ‏فَطَسَّ بِالْعَصَا فِي ذَلِكَ ‏ ‏الْقِنْوِ ‏ ‏ثُمَّ قَالَ ‏ ‏لَوْ شَاءَ رَبُّ هَذِهِ الصَّدَقَةِ تَصَدَّقَ بِأَطْيَبَ مِنْ هَذَا إِنَّ رَبَّ هَذِهِ الصَّدَقَةِ يَأْكُلُ ‏ ‏الْحَشَفَ ‏ ‏يَوْمَ الْقِيَامَةِ ‏","","",""],[22874,22874,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏فَرَجُ بْنُ فَضَالَةَ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏مُسْلِمِ بْنِ قَرَظَةَ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏خِيَارُكُمْ وَخِيَارُ أَئِمَّتِكُمْ الَّذِينَ تُحِبُّونَهُمْ وَيُحِبُّونَكُمْ وَتُصَلُّونَ عَلَيْهِمْ وَيُصَلُّونَ عَلَيْكُمْ وَشِرَارُكُمْ وَشِرَارُ أَئِمَّتِكُمْ الَّذِينَ تُبْغِضُونَهُمْ وَيُبْغِضُونَكُمْ وَتَلْعَنُونَهُمْ وَيَلْعَنُونَكُمْ قَالُوا يَا رَسُولَ اللَّهِ أَفَلَا نُقَاتِلُهُمْ قَالَ لَا مَا صَلَّوْا لَكُمْ ‏ ‏الْخَمْسَ ‏ ‏أَلَا وَمَنْ عَلَيْهِ وَالٍ فَرَآهُ يَأْتِي شَيْئًا مِنْ مَعَاصِي اللَّهِ فَلْيَكْرَهْ مَا أَتَى وَلَا تَنْزِعُوا يَدًا مِنْ طَاعَتِهِ ‏","","",""],[22875,22875,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى مَيِّتٍ قَالَ فَفَهِمْتُ مِنْ صَلَاتِهِ عَلَيْهِ اللَّهُمَّ اغْفِرْ لَهُ وَارْحَمْهُ وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَنَقِّهِ مِنْ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنْ ‏ ‏الدَّنَسِ ‏","","",""],[22876,22876,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ بْنِ صَالِحٍ ‏ ‏عَنْ ‏ ‏أَزْهَرَ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏ذِي كَلَاعٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقُصَّاصُ ثَلَاثَةٌ أَمِيرٌ أَوْ ‏ ‏مَأْمُورٌ ‏ ‏أَوْ ‏ ‏مُخْتَالٌ ‏","","",""],[22877,22877,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَبِي مَلِيحٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏عَرَّسَ ‏ ‏بِنَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ لَيْلَةٍ ‏ ‏فَافْتَرَشَ ‏ ‏كُلُّ رَجُلٍ مِنَّا ذِرَاعَ رَاحِلَتِهِ قَالَ فَانْتَهَيْتُ إِلَى بَعْضِ ‏ ‏الْإِبِلِ ‏ ‏فَإِذَا نَاقَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيْسَ قُدَّامَهَا أَحَدٌ قَالَ فَانْطَلَقْتُ أَطْلُبُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏وَعَبْدُ اللَّهِ بْنُ قَيْسٍ ‏ ‏قَائِمَانِ قُلْتُ أَيْنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَا مَا نَدْرِي غَيْرَ أَنَّا سَمِعْنَا صَوْتًا بِأَعْلَى ‏ ‏الْوَادِي ‏ ‏فَإِذَا مِثْلُ ‏ ‏هَزِيزِ ‏ ‏الرَّحْلِ قَالَ امْكُثُوا يَسِيرًا ثُمَّ جَاءَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنَّهُ أَتَانِي اللَّيْلَةَ آتٍ مِنْ رَبِّي فَخَيَّرَنِي بَيْنَ أَنْ يَدْخُلَ نِصْفُ أُمَّتِي الْجَنَّةَ وَبَيْنَ الشَّفَاعَةِ فَاخْتَرْتُ الشَّفَاعَةَ فَقُلْنَا ‏ ‏نَنْشُدُكَ ‏ ‏اللَّهَ وَالصُّحْبَةَ لَمَا جَعَلْتَنَا مِنْ أَهْلِ شَفَاعَتِكَ قَالَ فَإِنَّكُمْ مِنْ أَهْلِ شَفَاعَتِي قَالَ فَأَقْبَلْنَا ‏ ‏مَعَانِيقَ ‏ ‏إِلَى النَّاسِ فَإِذَا هُمْ قَدْ ‏ ‏فَزِعُوا وَفَقَدُوا نَبِيَّهُمْ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ ‏ ‏أَتَانِي اللَّيْلَةَ مِنْ رَبِّي آتٍ فَخَيَّرَنِي بَيْنَ أَنْ يَدْخُلَ نِصْفُ أُمَّتِي الْجَنَّةَ وَبَيْنَ الشَّفَاعَةِ وَإِنِّي اخْتَرْتُ الشَّفَاعَةَ قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏نَنْشُدُكَ ‏ ‏اللَّهَ وَالصُّحْبَةَ لَمَا جَعَلْتَنَا مِنْ أَهْلِ شَفَاعَتِكَ قَالَ فَلَمَّا أَضَبُّوا عَلَيْهِ قَالَ فَأَنَا أُشْهِدُكُمْ أَنَّ شَفَاعَتِي لِمَنْ لَا يُشْرِكُ بِاللَّهِ شَيْئًا مِنْ أُمَّتِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ الْهُذَلِيِّ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَشْجَعِيِّ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِهِ ‏ ‏فَأَنَاخَ ‏ ‏نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَنَخْنَا مَعَهُ ‏ ‏فَذَكَرَ مَعْنَاهُ إِلَّا أَنَّهُ قَالَ وَبَيْنَ أَنْ يَدْخُلَ نِصْفُ أُمَّتِي الْجَنَّةَ ‏","","",""],[22878,22878,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏صَفْوَانَ بْنِ عُمَرَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَاهُ الْفَيْءُ قَسَمَهُ مِنْ يَوْمِهِ فَأَعْطَى الْآهِلَ حَظَّيْنِ وَأَعْطَى ‏ ‏الْعَزَبَ ‏ ‏حَظًّا ‏","","",""],[22879,22879,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَاصِمٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏عَبْدُ الْحَمِيدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَالِحُ بْنُ أَبِي عَرِيبٍ ‏ ‏عَنْ ‏ ‏كَثِيرِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏دَخَلَ ‏ ‏عَوْفُ بْنُ مَالِكٍ ‏ ‏مَسْجِدَ ‏ ‏حِمْصَ ‏ ‏قَالَ وَإِذَا النَّاسُ عَلَى رَجُلٍ فَقَالَ مَا هَذِهِ الْجَمَاعَةُ قَالُوا ‏ ‏كَعْبٌ ‏ ‏يَقُصُّ قَالَ يَا وَيْحَهُ أَلَا سَمِعَ قَوْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَقُصُّ إِلَّا أَمِيرٌ أَوْ ‏ ‏مَأْمُورٌ ‏ ‏أَوْ ‏ ‏مُخْتَالٌ ‏","","",""],[22880,22880,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏النَّهَّاسُ ‏ ‏عَنْ ‏ ‏شَدَّادٍ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا وَامْرَأَةٌ ‏ ‏سَفْعَاءُ ‏ ‏الْخَدَّيْنِ كَهَاتَيْنِ يَوْمَ الْقِيَامَةِ وَجَمَعَ بَيْنَ أُصْبُعَيْهِ السَّبَّابَةِ وَالْوُسْطَى امْرَأَةٌ ذَاتُ مَنْصِبٍ وَجَمَالٍ آمَتْ مِنْ زَوْجِهَا حَبَسَتْ نَفْسَهَا عَلَى أَيْتَامِهَا حَتَّى بَانُوا ‏ ‏أَوْ مَاتُوا ‏","","",""],[22881,22881,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏النَّهَّاسُ ‏ ‏عَنْ ‏ ‏شَدَّادٍ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ عَبْدٍ مُسْلِمٍ يَكُونُ لَهُ ثَلَاثُ بَنَاتٍ فَأَنْفَقَ عَلَيْهِنَّ حَتَّى ‏ ‏يَبِنَّ ‏ ‏أَوْ يَمُتْنَ إِلَّا كُنَّ لَهُ حِجَابًا مِنْ النَّارِ فَقَالَتْ امْرَأَةٌ يَا رَسُولَ اللَّهِ أَوْ اثْنَتَانِ قَالَ أَوْ اثْنَتَانِ ‏","","",""],[22882,22882,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏النَّهَّاسِ ‏ ‏عَنْ ‏ ‏شَدَّادٍ أَبِي عَمَّارٍ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَا وَامْرَأَةٌ ‏ ‏سَفْعَاءُ ‏ ‏فِي الْجَنَّةِ كَهَاتَيْنِ امْرَأَةٌ آمَتْ مِنْ زَوْجِهَا فَحَبَسَتْ نَفْسَهَا عَلَى يَتَامَاهَا حَتَّى ‏ ‏بَانُوا ‏ ‏أَوْ مَاتُوا ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏فِي تَفْسِيرِ ‏ ‏شَيْبَانَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏صَاحِبٌ لَنَا أَظُنُّهُ ‏ ‏أَبَا الْمَلِيحِ الْهُذَلِيَّ ‏ ‏عَنْ ‏ ‏عَوْفِ بْنِ مَالِكٍ ‏ ‏فَذَكَرَهُ ‏ ‏وَقَالَ ‏ ‏بَيْنَ أَنْ يَدْخُلَ نِصْفُ أُمَّتِي الْجَنَّةَ ‏ ‏آخِرُ مُسْنَدِ ‏ ‏عَوْفِ بْنِ مَالِكٍ الْأَنْصَارِيِّ ‏ ‏وَهُوَ تَمَامُ مُسْنَدِ ‏ ‏الْأَنْصَارِ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏","","",""],[22883,22883,"","","‏ ‏قَالَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏سَمِعْتُهُ وَحْدِي ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ قَتْلِ حَيَّاتِ الْبُيُوتِ إِلَّا ‏ ‏الْأَبْتَرَ ‏ ‏وَذَا الطُّفْيَتَيْنِ ‏ ‏فَإِنَّهُمَا يَخْتَطِفَانِ ‏ ‏أَوْ قَالَ يَطْمِسَانِ ‏ ‏الْأَبْصَارَ وَيَطْرَحَانِ الْحَمْلَ مِنْ بُطُونِ النِّسَاءِ وَمَنْ تَرَكَهُمَا فَلَيْسَ مِنَّا ‏","","",""],[22884,22884,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ يَوْمُ عَاشُورَاءَ ‏ ‏يَوْمًا يَصُومُهُ ‏ ‏قُرَيْشٌ ‏ ‏فِي الْجَاهِلِيَّةِ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُهُ فَلَمَّا قَدِمَ ‏ ‏الْمَدِينَةَ ‏ ‏صَامَهُ وَأَمَرَ بِصِيَامِهِ فَلَمَّا نَزَلَتْ فَرِيضَةُ شَهْرِ رَمَضَانَ كَانَ رَمَضَانُ هُوَ الَّذِي يَصُومُهُ وَتَرَكَ يَوْمَ عَاشُورَاءَ فَمَنْ شَاءَ صَامَهُ وَمَنْ شَاءَ أَفْطَرَهُ ‏","","",""],[22885,22885,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ عَبَّادٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ لَهَا ‏ ‏إِنِّي أَعْرِفُ غَضَبَكِ إِذَا غَضِبْتِ وَرِضَاكِ إِذَا رَضِيتِ قَالَتْ وَكَيْفَ تَعْرِفُ ذَلِكَ يَا رَسُولَ اللَّهِ قَالَ إِذَا غَضِبْتِ قُلْتِ يَا ‏ ‏مُحَمَّدُ ‏ ‏وَإِذَا رَضِيتِ قُلْتِ يَا رَسُولَ اللَّهِ ‏","","",""],[22886,22886,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عُمَرُ بْنُ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلَ عُذْرِي مِنْ السَّمَاءِ ‏ ‏جَاءَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَنِي بِذَلِكَ فَقُلْتُ نَحْمَدُ اللَّهَ عَزَّ وَجَلَّ لَا نَحْمَدُكَ ‏","","",""],[22887,22887,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ مِنْ الْجَنَابَةِ ‏","","",""],[22888,22888,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّمَا ‏ ‏أَذِنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِسَوْدَةَ بِنْتِ زَمْعَةَ ‏ ‏فِي ‏ ‏الْإِفَاضَةِ ‏ ‏قَبْلَ الصُّبْحِ مِنْ ‏ ‏جَمْعٍ ‏ ‏لِأَنَّهَا كَانَتْ امْرَأَةً ‏ ‏ثَبِطَةً ‏","","",""],[22889,22889,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي حُجْرَتِي وَالنَّاسُ يَأْتَمُّونَ بِهِ مِنْ وَرَاءِ الْحُجْرَةِ يُصَلُّونَ بِصَلَاتِهِ ‏","","",""],[22890,22890,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏أَبِي حُرَّةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ هِشَامٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا قَامَ مِنْ اللَّيْلِ ‏ ‏يُصَلِّي افْتَتَحَ صَلَاتَهُ بِرَكْعَتَيْنِ خَفِيفَتَيْنِ ‏","","",""],[22891,22891,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ لِأَهْلِ بَيْتٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فِي الرُّقْيَةِ مِنْ كُلِّ ذِي حُمَةٍ ‏","","",""],[22892,22892,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ التَّطَوُّعِ فَقَالَتْ كَانَ ‏ ‏يُصَلِّي قَبْلَ الظُّهْرِ أَرْبَعًا فِي بَيْتِي ثُمَّ يَخْرُجُ فَيُصَلِّي بِالنَّاسِ ثُمَّ يَرْجِعُ إِلَى بَيْتِي فَيُصَلِّي رَكْعَتَيْنِ وَكَانَ ‏ ‏يُصَلِّي بِالنَّاسِ الْمَغْرِبَ ثُمَّ يَرْجِعُ إِلَى بَيْتِهِ فَيُصَلِّي رَكْعَتَيْنِ وَكَانَ ‏ ‏يُصَلِّي بِهِمْ الْعِشَاءَ ثُمَّ يَدْخُلُ بَيْتِي فَيُصَلِّي رَكْعَتَيْنِ وَكَانَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ تِسْعَ رَكَعَاتٍ فِيهِنَّ الْوَتْرُ وَكَانَ ‏ ‏يُصَلِّي لَيْلًا طَوِيلًا قَائِمًا وَلَيْلًا طَوِيلًا جَالِسًا فَإِذَا قَرَأَ وَهُوَ قَائِمٌ رَكَعَ وَسَجَدَ وَهُوَ قَائِمٌ وَإِذَا قَرَأَ وَهُوَ قَاعِدٌ رَكَعَ وَسَجَدَ وَهُوَ قَاعِدٌ وَكَانَ إِذَا طَلَعَ الْفَجْرُ صَلَّى رَكْعَتَيْنِ ثُمَّ يَخْرُجُ فَيُصَلِّي بِالنَّاسِ صَلَاةَ الْفَجْرِ ‏","","",""],[22893,22893,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ أَبِي خَالِدٍ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدَيَّ ‏ ‏قَالَ ‏ ‏مَسْرُوقٌ ‏ ‏فَسَمِعْتُ ‏ ‏تَصْفِيقَهَا بِيَدَيْهَا مِنْ وَرَاءِ الْحِجَابِ وَهِيَ تُحَدِّثُ بِذَلِكَ ثُمَّ تُقِيمُ فِينَا حَلَالًا ‏","","",""],[22894,22894,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏يَزِيدُ بْنُ أَبِي زِيَادٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ ‏ ‏الرُّكْبَانُ ‏ ‏يَمُرُّونَ بِنَا وَنَحْنُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُحْرِمَاتٌ فَإِذَا حَاذَوْا بِنَا أَسْدَلَتْ إِحْدَانَا جِلْبَابَهَا مِنْ رَأْسِهَا عَلَى وَجْهِهَا فَإِذَا جَاوَزَنَا كَشَفْنَاهُ ‏","","",""],[22895,22895,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏أَبِي الْعَالِيَةِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي سُجُودِ الْقُرْآنِ سَجَدَ وَجْهِي لِمَنْ ‏ ‏خَلَقَهُ وَشَقَّ سَمْعَهُ وَبَصَرَهُ ‏ ‏بِحَوْلِهِ ‏ ‏وَقُوَّتِهِ ‏","","",""],[22896,22896,"","","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا اسْتَرَاثَ الْخَبَرَ تَمَثَّلَ فِيهِ بِبَيْتِ ‏ ‏طَرَفَةَ ‏ ‏وَيَأْتِيكَ بِالْأَخْبَارِ مَنْ لَمْ ‏ ‏تُزَوِّدِ ‏","","",""],[22897,22897,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ يَعْنِي ابْنَ سُوَيْدٍ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏النَّقِيرِ ‏ ‏وَالْمُقَيَّرِ ‏ ‏وَالدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏","","",""],[22898,22898,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَالِدًا ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّ الضُّحَى إِلَّا أَنْ يَقْدَمَ مِنْ سَفَرٍ فَيُصَلِّي رَكْعَتَيْنِ ‏","","",""],[22899,22899,"","","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرٌ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي مُلَيْكَةَ ‏ ‏عَنِ ‏ ‏ابْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُحَرِّمُ الْمَصَّةُ وَالْمَصَّتَانِ ‏","","",""],[22900,22900,"","","‏ ‏أَنْبَأَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏حَدَّثَنَا ‏ ‏بُرْدٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فِي الْبَيْتِ وَالْبَابُ عَلَيْهِ مُغْلَقٌ فَجِئْتُ فَمَشَى حَتَّى فَتَحَ لِي ثُمَّ رَجَعَ إِلَى مَقَامِهِ ‏ ‏وَوَصَفَتْ أَنَّ الْبَابَ فِي الْقِبْلَةِ ‏","","",""],[22901,22901,"","","‏ ‏أَنْبَأَنَا ‏ ‏بِشْرُ بْنُ الْمُفَضَّلِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏قَالَ ‏ ‏دَخَلْنَا عَلَى ‏ ‏حَفْصَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏فَأَخْبَرَتْنَا أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَنْ الْغُلَامِ شَاتَانِ ‏ ‏مُكَافَأَتَانِ ‏ ‏وَعَنْ الْجَارِيَةِ شَاةٌ ‏","","",""],[22902,22902,"","","‏ ‏حَدَّثَنَا ‏ ‏مَرْحُومُ بْنُ عَبْدِ الْعَزِيزِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ بَابَنُوسَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏دَخَلَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ وَفَاتِهِ فَوَضَعَ فَمَهُ بَيْنَ عَيْنَيْهِ وَوَضَعَ يَدَيْهِ عَلَى ‏ ‏صُدْغَيْهِ ‏ ‏وَقَالَ وَا ‏ ‏نَبِيَّاهْ وَا ‏ ‏خَلِيلَاهْ وَا ‏ ‏صَفِيَّاهْ ‏","","",""],[22903,22903,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ يَعْنِي الْأَزْرَقَ ‏ ‏وَيَحْيَى بْنُ سَعِيدٍ ‏ ‏قَالَ ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنُ بْنُ الْمُكْتَبِ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي الْجَوْزَاءِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْتَتِحُ الصَّلَاةَ بِالتَّكْبِيرِ وَالْقِرَاءَةِ بِ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏وَكَانَ إِذَا رَكَعَ لَمْ يَرْفَعْ رَأْسَهُ ‏ ‏وَقَالَ ‏ ‏يَحْيَى ‏ ‏يُشْخِصُ رَأْسَهُ ‏ ‏وَلَمْ ‏ ‏يُصَوِّبْهُ ‏ ‏وَلَكِنْ بَيْنَ ذَلِكَ وَكَانَ إِذَا رَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ لَمْ يَسْجُدْ حَتَّى يَسْتَوِيَ قَائِمًا وَإِذَا رَفَعَ رَأْسَهُ مِنْ السُّجُودِ لَمْ يَسْجُدْ حَتَّى يَسْتَوِيَ جَالِسًا قَالَتْ وَكَانَ يَقُولُ فِي كُلِّ رَكْعَتَيْنِ التَّحِيَّةَ وَكَانَ يَنْهَى عَنْ ‏ ‏عَقِبِ ‏ ‏الشَّيْطَانِ وَكَانَ ‏ ‏يَفْتَرِشُ ‏ ‏رِجْلَهُ الْيُسْرَى وَيَنْصِبُ رِجْلَهُ الْيُمْنَى وَكَانَ يَنْهَى أَنْ ‏ ‏يَفْتَرِشَ ‏ ‏أَحَدُنَا ذِرَاعَيْهِ كَالْكَلْبِ وَكَانَ يَخْتِمُ الصَّلَاةَ بِالتَّسْلِيمِ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏وَكَانَ يَكْرَهُ أَنْ ‏ ‏يَفْتَرِشَ ‏ ‏ذِرَاعَيْهِ ‏ ‏افْتِرَاشَ ‏ ‏السَّبُعِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي الْجَوْزَاءِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ وَقَالَ ‏ ‏يُشْخِصُ ‏ ‏رَأْسَهُ وَقَالَ ‏ ‏افْتِرَاشَ ‏ ‏السَّبُعِ ‏","","",""],[22904,22904,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَيَحْيَى ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ أَطْيَبَ مَا أَكَلَ الرَّجُلُ مِنْ كَسْبِهِ وَإِنَّ وَلَدَهُ مِنْ كَسْبِهِ ‏","","",""],[22905,22905,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُصَيْنٌ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏فَرْوَةَ بْنِ نَوْفَلٍ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ دُعَاءِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلَتْهُ نَفْسِي ‏","","",""],[22906,22906,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا ضَرَبَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَادِمًا لَهُ قَطُّ وَلَا امْرَأَةً لَهُ قَطُّ وَلَا ضَرَبَ بِيَدِهِ إِلَّا أَنْ يُجَاهِدَ فِي سَبِيلِ اللَّهِ وَمَا نِيلَ مِنْهُ شَيْءٌ فَانْتَقَمَهُ مِنْ صَاحِبِهِ إِلَّا أَنْ ‏ ‏تُنْتَهَكَ ‏ ‏مَحَارِمُ اللَّهِ عَزَّ وَجَلَّ فَيَنْتَقِمُ لِلَّهِ عَزَّ وَجَلَّ وَمَا عُرِضَ عَلَيْهِ أَمْرَانِ أَحَدُهُمَا أَيْسَرُ مِنْ الْآخَرِ إِلَّا أَخَذَ بِأَيْسَرِهِمَا إِلَّا أَنْ يَكُونَ مَأْثَمًا فَإِنْ كَانَ مَأْثَمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ ‏","","",""],[22907,22907,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ يَعْنِي ابْنَ عُلَيَّةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ السَّائِبِ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَخَذَ أَهْلَهُ ‏ ‏الْوَعْكُ ‏ ‏أَمَرَ بِالْحَسَاءِ فَصُنِعَ ثُمَّ أَمَرَهُمْ ‏ ‏فَحَسَوْا ‏ ‏مِنْهُ ثُمَّ يَقُولُ إِنَّهُ ‏ ‏يَعْنِي لَيَرْتُو فُؤَادَ الْحَزِينِ ‏ ‏وَيَسْرُو عَنْ فُؤَادِ ‏ ‏السَّقِيمِ ‏ ‏كَمَا ‏ ‏تَسْرُو إِحْدَاكُنَّ الْوَسَخَ بِالْمَاءِ عَنْ وَجْهِهَا ‏","","",""],[22908,22908,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلَتْ امْرَأَةٌ ‏ ‏عَائِشَةَ ‏ ‏أَتَقْضِي الْحَائِضُ الصَّلَاةَ فَقَالَتْ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ قَدْ ‏ ‏كُنَّا نَحِيضُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَا ‏ ‏نَقْضِي وَلَا نُؤْمَرُ بِقَضَاءٍ ‏","","",""],[22909,22909,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏عَنْ ‏ ‏أَبِي بُرْدَةَ ‏ ‏قَالَ ‏ ‏أَخْرَجَتْ إِلَيْنَا ‏ ‏عَائِشَةُ ‏ ‏كِسَاءً ‏ ‏مُلَبَّدًا ‏ ‏وَإِزَارًا غَلِيظًا فَقَالَتْ ‏ ‏قُبِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي هَذَيْنِ ‏","","",""],[22910,22910,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏رَضِيعًا كَانَ ‏ ‏لِعَائِشَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَمُوتُ أَحَدٌ مِنْ الْمُسْلِمِينَ فَيُصَلِّي عَلَيْهِ أُمَّةٌ مِنْ النَّاسِ يَبْلُغُونَ أَنْ يَكُونُوا مِائَةً فَيَشْفَعُوا لَهُ إِلَّا شُفِّعُوا فِيهِ ‏","","",""],[22911,22911,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنِ ‏ ‏ابْنِ عَوْنٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ ‏ ‏ذَكَرُوا عِنْدَ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏عَلِيًّا ‏ ‏كَانَ وَصِيًّا فَقَالَتْ مَتَى أَوْصَى إِلَيْهِ فَقَدْ ‏ ‏كُنْتُ مُسْنِدَتَهُ إِلَى صَدْرِي ‏ ‏أَوْ قَالَتْ فِي حِجْرِي ‏ ‏فَدَعَا بِالطَّسْتِ فَلَقَدْ ‏ ‏انْخَنَثَ ‏ ‏فِي حِجْرِي وَمَا شَعَرْتُ أَنَّهُ مَاتَ فَمَتَى أَوْصَى إِلَيْهِ ‏","","",""],[22912,22912,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏أَبِي عَطِيَّةَ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏إِنِّي لَأَعْلَمُ كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي قَالَ ثُمَّ سَمِعْتُهَا ‏ ‏تُلَبِّي تَقُولُ ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ لَا شَرِيكَ لَكَ ‏","","",""],[22913,22913,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏تَمِيمِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعْتَكِفُ ‏ ‏فَيُخْرِجُ إِلَيَّ رَأْسَهُ مِنْ الْمَسْجِدِ فَأَغْسِلُهُ وَأَنَا حَائِضٌ ‏","","",""],[22914,22914,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ الجَزَّارِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوتِرُ بِتِسْعٍ فَلَمَّا أَسَنَّ وَثَقُلَ أَوْتَرَ بِسَبْعٍ ‏","","",""],[22915,22915,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْأَعْمَشُ ‏ ‏عَنْ ‏ ‏أَبِي صَالِحٍ ‏ ‏قَالَ سُئِلَتْ ‏ ‏عَائِشَةُ ‏ ‏وَأُمُّ سَلَمَةَ ‏ ‏أَيُّ الْعَمَلِ كَانَ أَعْجَبَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتَا مَا دَامَ وَإِنْ قَلَّ ‏","","",""],[22916,22916,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُونُسُ بْنُ عُمَرٍو ‏ ‏عَنِ ‏ ‏الْعَيْزَارِ بْنِ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُومُ وَيُصَلِّي وَعَلَيْهِ طَرَفُ اللِّحَافِ وَعَلَى ‏ ‏عَائِشَةَ ‏ ‏طَرَفُهُ ثُمَّ ‏ ‏يُصَلِّي ‏","","",""],[22917,22917,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّها قَالَتْ ‏ ‏انْكَسَفَتْ الشَّمْسُ ‏ ‏فَصَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَطَالَ الْقِيَامَ ثُمَّ رَكَعَ فَأَطَالَ الرُّكُوعَ ثُمَّ رَفَعَ قَبْلَ أَنْ يَسْجُدَ فَأَطَالَ الْقِيَامَ وَهُوَ دُونَ الْقِيَامِ الْأَوَّلِ ثُمَّ رَكَعَ فَأَطَالَ دُونَ الرُّكُوعِ الْأَوَّلِ ثُمَّ سَجَدَ ثُمَّ قَامَ الثَّانِيَةَ ثُمَّ ‏ ‏فَعَلَ مِثْلَ مَا فَعَلَ فِي الرَّكْعَةِ الْأُولَى غَيْرَ أَنَّ أَوَّلَ قِيَامِهِ أَطْوَلُ مِنْ آخِرِهِ وَأَوَّلَ رُكُوعِهِ أَطْوَلُ مِنْ آخِرِهِ فَقَضَى صَلَاتَهُ وَقَدْ تَجَلَّتْ الشَّمْسُ ‏","","",""],[22918,22918,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ فُضَيْلٍ ‏ ‏عَنِ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُبَاشِرُ ‏ ‏نِسَاءَهُ فَوْقَ الْإِزَارِ وَهُنَّ حُيَّضٌ ‏","","",""],[22919,22919,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏وَمَرْوَانَ بْنِ شُجَاعٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَقَالَ ‏ ‏مَرْوَانُ ‏ ‏سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ قَالَتْ ‏ ‏لَمَّا ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ لُبْسِ الذَّهَبِ قُلْنَا يَا رَسُولَ اللَّهِ أَلَا نَرْبِطُ الْمِسْكَ بِشَيْءٍ مِنْ ذَهَبٍ قَالَ أَفَلَا تَرْبِطُونَهُ بِالْفِضَّةِ ثُمَّ تَلْطَخُونَهُ بِزَعْفَرَانَ فَيَكُونَ مِثْلَ الذَّهَبِ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏خُصَيْفٍ ‏ ‏وَحَدَّثَنَا ‏ ‏مَرْوَانُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خُصَيْفٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنِ ‏ ‏أُمِّ سَلَمَةَ ‏ ‏مِثْلَ ذَلِكَ ‏","","",""],[22920,22920,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏قَالَ أَنْبَأَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏دَخَلَ عَلَيْهَا وَعِنْدَهَا ‏ ‏جَارِيَتَانِ تَضْرِبَانِ بِدُفَّيْنِ ‏ ‏فَانْتَهَرَهُمَا ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهُنَّ فَإِنَّ لِكُلِّ قَوْمٍ عِيدًا ‏","","",""],[22921,22921,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أَقْسَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ لَا يَدْخُلَ عَلَى نِسَائِهِ شَهْرًا قَالَتْ فَلَبِثَ تِسْعًا وَعِشْرِينَ قَالَتْ فَكُنْتُ أَوَّلَ مَنْ بَدَأَ بِهِ فَقُلْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَيْسَ كُنْتَ أَقْسَمْتَ شَهْرًا فَعَدَّتْ الْأَيَّامُ تِسْعًا وَعِشْرِينَ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّهْرُ تِسْعٌ وَعِشْرُونَ ‏","","",""],[22922,22922,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنَّ النِّسَاءُ يُصَلِّينَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْغَدَاةَ ‏ ‏ثُمَّ يَخْرُجْنَ ‏ ‏مُتَلَفِّعَاتٍ ‏ ‏بِمُرُوطِهِنَّ ‏ ‏لَا يُعْرَفْنَ ‏","","",""],[22923,22923,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمْسٌ ‏ ‏فَوَاسِقُ ‏ ‏يُقْتَلْنَ فِي الْحَرَمِ الْعَقْرَبُ وَالْفَأْرَةُ وَالْحُدَيَّا وَالْكَلْبُ ‏ ‏الْعَقُورُ ‏ ‏وَالْغُرَابُ ‏","","",""],[22924,22924,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏بَرِيرَةَ ‏ ‏أَتَتْهَا تَسْتَعِينُهَا وَكَانَتْ ‏ ‏مُكَاتَبَةً ‏ ‏فَقَالَتْ لَهَا ‏ ‏عَائِشَةُ ‏ ‏أَيَبِيعُكِ أَهْلُكِ فَأَتَتْ أَهْلَهَا فَذَكَرَتْ ذَلِكَ لَهُمْ فَقَالُوا لَا إِلَّا أَنْ تَشْتَرِطَ لَنَا ‏ ‏وَلَاءَهَا ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اشْتَرِيهَا فَأَعْتِقِيهَا فَإِنَّمَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ ‏","","",""],[22925,22925,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏أَفْلَحَ ‏ ‏أَخَا ‏ ‏أَبِي قُعَيْسٍ ‏ ‏اسْتَأْذَنَ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَأَبَتْ أَنْ تَأْذَنَ لَهُ فَلَمَّا أَنْ جَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَفْلَحَ ‏ ‏أَخَا ‏ ‏أَبِي قُعَيْسٍ ‏ ‏اسْتَأْذَنَ عَلَيَّ فَأَبَيْتُ أَنْ آذَنَ لَهُ فَقَالَ ائْذَنِي لَهُ قَالَتْ يَا رَسُولَ اللَّهِ إِنَّمَا أَرْضَعَتْنِي الْمَرْأَةُ وَلَمْ يُرْضِعْنِي الرَّجُلُ قَالَ ‏ ‏ائْذَنِي لَهُ فَإِنَّهُ عَمُّكِ ‏ ‏تَرِبَتْ ‏ ‏يَمِينُكِ ‏","","",""],[22926,22926,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ امْرَأَةً دَخَلَتْ عَلَيْهَا وَمَعَهَا ابْنَتَانِ لَهَا فَأَعْطَيْتُهَا تَمْرَةً فَشَقَّتْهَا بَيْنَهُمَا فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَنْ ابْتُلِيَ بِشَيْءٍ مِنْ هَذِهِ الْبَنَاتِ فَأَحْسَنَ إِلَيْهِنَّ كُنَّ لَهُ سِتْرًا مِنْ النَّارِ ‏","","",""],[22927,22927,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَتْرُكُ الْعَمَلَ وَهُوَ يُحِبُّ أَنْ يَعْمَلَهُ ‏ ‏كَرَاهِيَةَ أَنْ ‏ ‏يَسْتَنَّ ‏ ‏النَّاسُ بِهِ فَيُفْرَضَ عَلَيْهِمْ فَكَانَ يُحِبُّ مَا خُفِّفَ عَلَيْهِمْ مِنْ الْفَرَائِضِ ‏","","",""],[22928,22928,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بَعْدَ الْعِشَاءِ إِحْدَى عَشْرَةَ رَكْعَةً فَإِذَا أَصْبَحَ صَلَّى رَكْعَتَيْنِ خَفِيفَتَيْنِ ثُمَّ اضْطَجَعَ عَلَى شِقِّهِ الْأَيْمَنِ حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ فَيُؤْذِنَهُ بِالصَّلَاةِ ‏","","",""],[22929,22929,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَتْ ‏ ‏امْرَأَةُ رِفَاعَةَ الْقُرَظِيِّ ‏ ‏وَأَنَا ‏ ‏وَأَبُو بَكْرٍ ‏ ‏عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏إِنَّ ‏ ‏رِفَاعَةَ ‏ ‏طَلَّقَنِي ‏ ‏الْبَتَّةَ ‏ ‏وَإِنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الزُّبَيْرِ ‏ ‏تَزَوَّجَنِي وَإِنَّمَا عِنْدَهُ مِثْلُ هُدْبَتِي وَأَخَذَتْ ‏ ‏هُدْبَةً ‏ ‏مِنْ جِلْبَابِهَا ‏ ‏وَخَالِدُ بْنُ سَعِيدِ بْنِ الْعَاصِ ‏ ‏بِالْبَابِ لَمْ يُؤْذَنْ لَهُ فَقَالَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏أَلَا ‏ ‏تَنْهَى هَذِهِ عَمَّا تَجْهَرُ بِهِ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَا زَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى التَّبَسُّمِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَأَنَّكِ تُرِيدِينَ أَنْ تَرْجِعِي إِلَى ‏ ‏رِفَاعَةَ ‏ ‏لَا حَتَّى تَذُوقِي عُسَيْلَتَهُ وَيَذُوقَ عُسَيْلَتَكِ ‏","","",""],[22930,22930,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَعْتَمَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْعِشَاءِ حَتَّى نَادَاهُ ‏ ‏عُمَرُ بْنُ الْخَطَّابِ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏قَدْ نَامَ النِّسَاءُ وَالصِّبْيَانُ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنَّهُ لَيْسَ أَحَدٌ مِنْ أَهْلِ الْأَرْضِ ‏ ‏يُصَلِّي هَذِهِ الصَّلَاةَ غَيْرَكُمْ ‏ ‏وَلَمْ يَكُنْ أَحَدٌ ‏ ‏يُصَلِّي يَوْمَئِذٍ غَيْرَ أَهْلِ ‏ ‏الْمَدِينَةِ ‏","","",""],[22931,22931,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبَّاسٍ ‏ ‏وَعَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهُمَا قَالَا ‏ ‏لَمَّا نَزَلَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏طَفِقَ ‏ ‏يُلْقِي خَمِيصَتَهُ عَلَى وَجْهِهِ فَإِذَا ‏ ‏اغْتَمَّ ‏ ‏رَفَعْنَاهَا عَنْهُ وَهُوَ يَقُولُ ‏ ‏لَعَنَ اللَّهُ ‏ ‏الْيَهُودَ ‏ ‏وَالنَّصَارَى ‏ ‏اتَّخَذُوا قُبُورَ أَنْبِيَائِهِمْ مَسَاجِدَ ‏ ‏تَقُولُ ‏ ‏عَائِشَةُ ‏ ‏يُحَذِّرُهُمْ مِثْلَ الَّذِي صَنَعُوا ‏","","",""],[22932,22932,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا مَرِضَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِ ‏ ‏مَيْمُونَةَ ‏ ‏فَاسْتَأْذَنَ نِسَاءَهُ أَنْ يُمَرَّضَ فِي بَيْتِي فَأَذِنَّ لَهُ فَخَرَجَ رَسُولُ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُعْتَمِدًا عَلَى ‏ ‏الْعَبَّاسِ ‏ ‏وَعَلَى رَجُلٍ آخَرَ وَرِجْلَاهُ ‏ ‏تَخُطَّانِ ‏ ‏فِي الْأَرْضِ ‏ ‏وَقَالَ ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏فَقَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَتَدْرِي مَنْ ذَلِكَ الرَّجُلُ هُوَ ‏ ‏عَلِيُّ بْنُ أَبِي طَالِبٍ ‏ ‏وَلَكِنَّ ‏ ‏عَائِشَةَ ‏ ‏لَا تَطِيبُ لَهَا نَفْسًا ‏ ‏قَالَ ‏ ‏الزُّهْرِيُّ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي بَيْتِ ‏ ‏مَيْمُونَةَ ‏ ‏لِعَبْدِ اللَّهِ بْنِ زَمْعَةَ ‏ ‏مُرْ النَّاسَ فَلْيُصَلُّوا فَلَقِيَ ‏ ‏عُمَرَ بْنَ الْخَطَّابِ ‏ ‏فَقَالَ يَا ‏ ‏عُمَرُ ‏ ‏صَلِّ بِالنَّاسِ فَصَلَّى بِهِمْ فَسَمِعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَوْتَهُ فَعَرَفَهُ وَكَانَ جَهِيرَ الصَّوْتِ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَيْسَ هَذَا صَوْتَ ‏ ‏عُمَرَ ‏ ‏قَالُوا بَلَى قَالَ ‏ ‏يَأْبَى اللَّهُ جَلَّ وَعَزَّ ذَلِكَ وَالْمُؤْمِنُونَ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏رَجُلٌ رَقِيقٌ لَا يَمْلِكُ دَمْعَهُ وَإِنَّهُ إِذَا قَرَأَ الْقُرْآنَ بَكَى قَالَ وَمَا قُلْتِ ذَلِكَ إِلَّا كَرَاهِيَةَ أَنْ يَتَأَثَّمَ النَّاسُ ‏ ‏بِأَبِي بَكْرٍ ‏ ‏أَنْ يَكُونَ أَوَّلَ مَنْ قَامَ مَقَامَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ فَرَاجَعَتْهُ فَقَالَ ‏ ‏مُرُوا ‏ ‏أَبَا بَكْرٍ ‏ ‏فَلْيُصَلِّ بِالنَّاسِ إِنَّكُمْ صَوَاحِبُ ‏ ‏يُوسُفَ ‏","","",""],[22933,22933,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْأَعْلَى ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ الْحَارِثِ بْنِ هِشَامٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ أَنَا وَأَبِي عَلَى ‏ ‏عَائِشَةَ ‏ ‏وَأُمِّ سَلَمَةَ ‏ ‏فَقَالَتَا ‏ ‏إِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يُصْبِحُ جُنُبًا ثُمَّ يَصُومُ ‏","","",""],[22934,22934,"","","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقُولُ فِي رُكُوعِهِ وَسُجُودِهِ سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ ‏","","",""],[22935,22935,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنِ ‏ ‏النَّخَعِيِّ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْرُكُهُ مِنْ ثَوْبِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا رَأَيْتَهُ فَاغْسِلْهُ وَإِلَّا فَرُشَّهُ ‏","","",""],[22936,22936,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏وَرِبْعِيِّ بْنِ إِبْرَاهِيمَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ فِي آخِرِ أَمْرِهِ مِنْ قَوْلِ ‏ ‏سُبْحَانَ اللَّهِ وَبِحَمْدِهِ أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ قَالَتْ فَقُلْتُ يَا رَسُولَ اللَّهِ مَا لِي أَرَاكَ تُكْثِرُ مِنْ قَوْلِ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ قَالَ إِنَّ رَبِّي عَزَّ وَجَلَّ كَانَ أَخْبَرَنِي أَنِّي ‏ ‏سَأَرَى عَلَامَةً فِي أُمَّتِي وَأَمَرَنِي إِذَا رَأَيْتُهَا أَنْ أُسَبِّحَ بِحَمْدِهِ وَأَسْتَغْفِرَهُ إِنَّهُ كَانَ تَوَّابًا فَقَدْ رَأَيْتُهَا ‏ { ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ إِنَّهُ كَانَ تَوَّابًا ‏}","","",""],[22937,22937,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلَ عُذْرِي قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ فَذَكَرَ ذَلِكَ وَتَلَا الْقُرْآنَ فَلَمَّا نَزَلَ أَمَرَ بِرَجُلَيْنِ وَامْرَأَةٍ فَضُرِبُوا حَدَّهُمْ ‏","","",""],[22938,22938,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏نَافِعٌ ‏ ‏وَكَانَتْ امْرَأَتُهُ ‏ ‏أُمَّ وَلَدٍ لِعَبْدِ اللَّهِ بْنِ عُمَرَ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏ابْتَاعَ ‏ ‏جَارِيَةً بِطَرِيقِ ‏ ‏مَكَّةَ ‏ ‏فَأَعْتَقَهَا وَأَمَرَهَا أَنْ تَحُجَّ مَعَهُ فَابْتَغَى لَهَا نَعْلَيْنِ فَلَمْ يَجِدْهُمَا فَقَطَعَ لَهَا خُفَّيْنِ أَسْفَلَ مِنْ الْكَعْبَيْنِ ‏ ‏قَالَ ‏ ‏ابْنُ إِسْحَاقَ ‏ ‏فَذَكَرْتُ ‏ ‏ذَلِكَ ‏ ‏لِابْنِ شِهَابٍ ‏ ‏فَقَالَ حَدَّثَنِي ‏ ‏سَالِمٌ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ ‏ ‏كَانَ يَصْنَعُ ذَلِكَ ‏ ‏ثُمَّ ‏ ‏حَدَّثَتْهُ ‏ ‏صَفِيَّةُ بِنْتُ أَبِي عُبَيْدٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُرَخِّصُ لِلنِّسَاءِ فِي الْخُفَّيْنِ فَتَرَكَ ذَلِكَ ‏","","",""],[22939,22939,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْعَثُ بِالْبُدْنِ مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏إِلَى ‏ ‏مَكَّةَ ‏ ‏وَأَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏الْبُدْنِ بِيَدَيَّ ثُمَّ يَأْتِي مَا يَأْتِي الْحَلَالُ قَبْلَ أَنْ تَبْلُغَ الْبُدْنُ ‏ ‏مَكَّةَ ‏","","",""],[22940,22940,"","","‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ ‏ ‏عَنْ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏أَنَا أَوَّلُ النَّاسِ سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ هَذِهِ الْآيَةِ ‏ { ‏يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَوَاتُ وَبَرَزُوا لِلَّهِ الْوَاحِدِ الْقَهَّارِ ‏} ‏قَالَتْ فَقُلْتُ أَيْنَ النَّاسُ يَوْمَئِذٍ يَا رَسُولَ اللَّهِ قَالَ عَلَى الصِّرَاطِ ‏","","",""],[22941,22941,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ إِحْدَى عَشْرَةَ رَكْعَةً يُوتِرُ مِنْهَا بِوَاحِدَةٍ فَإِذَا فَرَغَ مِنْ صَلَاتِهِ اضْطَجَعَ عَلَى شِقِّهِ الْأَيْمَنِ ‏","","",""],[22942,22942,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِينَ ‏ ‏أَهَلُّوا ‏ ‏بِالْعُمْرَةِ طَافُوا ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ طَافُوا بَعْدَ أَنْ رَجَعُوا مِنْ ‏ ‏مِنًى ‏ ‏لِحَجِّهِمْ وَالَّذِينَ قَرَنُوا طَافُوا طَوَافًا وَاحِدًا ‏","","",""],[22943,22943,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سَالِمٍ أَبِي النَّضْرِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ فَإِذَا فَرَغَ مِنْ صَلَاتِهِ اضْطَجَعَ فَإِنْ كُنْتُ يَقْظَانَةً ‏ ‏تَحَدَّثَ مَعِي وَإِنْ كُنْتُ نَائِمَةً نَامَ حَتَّى يَأْتِيَهُ الْمُؤَذِّنُ ‏","","",""],[22944,22944,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رَمَضَانَ فَقَالَتْ مَا كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَزِيدُ فِي رَمَضَانَ وَلَا غَيْرِهِ عَلَى إِحْدَى عَشْرَةَ رَكْعَةً ‏ ‏يُصَلِّي أَرْبَعًا فَلَا تَسْأَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ ثُمَّ ‏ ‏يُصَلِّي أَرْبَعًا فَلَا تَسْأَلْ عَنْ حُسْنِهِنَّ وَطُولِهِنَّ ثُمَّ ‏ ‏يُصَلِّي ثَلَاثًا قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ تَنَامُ قَبْلَ أَنْ تُوتِرَ قَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏إِنَّهُ أَوْ إِنِّي ‏ ‏تَنَامُ عَيْنَايَ وَلَا يَنَامُ قَلْبِي ‏","","",""],[22945,22945,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏وَعَبْدِ رَبِّهِ بْنِ سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏وَأُمِّ سَلَمَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصْبِحُ جُنُبًا مِنْ جِمَاعٍ غَيْرَ احْتِلَامٍ ثُمَّ يَصُومُ ‏ ‏وَقَالَتْ ‏ ‏فِي حَدِيثِ ‏ ‏عَبْدِ رَبِّهِ ‏ ‏فِي رَمَضَانَ ‏","","",""],[22946,22946,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ الْمَلِكِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ ‏ ‏نَذَرَ ‏ ‏أَنْ يُطِيعَ اللَّهَ جَلَّ وَعَزَّ فَلْيُطِعْهُ وَمَنْ ‏ ‏نَذَرَ ‏ ‏أَنْ يَعْصِيَ اللَّهَ جَلَّ وَعَزَّ فَلَا يَعْصِهِ ‏","","",""],[22947,22947,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏أَبِي الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمِنَّا مَنْ ‏ ‏أَهَلَّ ‏ ‏بِالْحَجِّ وَمِنَّا مَنْ ‏ ‏أَهَلَّ ‏ ‏بِالْعُمْرَةِ وَمِنَّا مَنْ ‏ ‏أَهَلَّ ‏ ‏بِالْحَجِّ وَالْعُمْرَةِ ‏ ‏وَأَهَلَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَجِّ فَأَمَّا مَنْ ‏ ‏أَهَلَّ ‏ ‏بِالْعُمْرَةِ فَأَحَلُّوا حِينَ طَافُوا ‏ ‏بِالْبَيْتِ ‏ ‏وَبِالصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏وَأَمَّا مَنْ ‏ ‏أَهَلَّ ‏ ‏بِالْحَجِّ أَوْ بِالْحَجِّ وَالْعُمْرَةِ فَلَمْ ‏ ‏يُحِلُّوا ‏ ‏إِلَى يَوْمِ النَّحْرِ ‏","","",""],[22948,22948,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْرَدَ بِالْحَجِّ ‏","","",""],[22949,22949,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ سَمِعْتُهُ مِنَ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْطَعُ فِي رُبُعِ الدِّينَارِ فَصَاعِدًا ‏","","",""],[22950,22950,"","","‏ ‏حَدَّثَنَا ‏ ‏عَتَّابٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ يَعْنِي ابْنَ الْمُبَارَكِ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏قَالَ قَالَتْ ‏ ‏عَمْرَةُ بِنْتُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تُقْطَعُ يَدُ السَّارِقِ فِي رُبُعِ دِينَارٍ فَصَاعِدًا ‏","","",""],[22951,22951,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلْتُ الْجَنَّةَ فَسَمِعْتُ فِيهَا قِرَاءَةً قُلْتُ مَنْ هَذَا قَالُوا ‏ ‏حَارِثَةُ بْنُ النُّعْمَانِ ‏ ‏كَذَاكُمْ ‏ ‏الْبِرُّ ‏ ‏كَذَاكُمْ ‏ ‏الْبِرُّ ‏ ‏وَقَالَ ‏ ‏مَرَّةً ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏إِنْ شَاءَ اللَّهُ ‏","","",""],[22952,22952,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ اسْتَتَرْتُ ‏ ‏بِقِرَامٍ ‏ ‏فِيهِ تَمَاثِيلُ فَلَمَّا رَآهُ ‏ ‏تَلَوَّنَ ‏ ‏وَجْهُهُ ‏ ‏وَقَالَ ‏ ‏مَرَّةً تَغَيَّرَ وَجْهُهُ ‏ ‏وَهَتَكَهُ بِيَدِهِ وَقَالَ ‏ ‏أَشَدُّ النَّاسِ عَذَابًا عِنْدَ اللَّهِ عَزَّ وَجَلَّ يَوْمَ الْقِيَامَةِ الَّذِينَ ‏ ‏يُضَاهُونَ ‏ ‏بِخَلْقِ اللَّهِ جَلَّ وَعَزَّ ‏ ‏أَوْ يُشَبِّهُونَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏سَوَاءٌ ‏","","",""],[22953,22953,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ شَرَابٍ أَسْكَرَ فَهُوَ حَرَامٌ ‏","","",""],[22954,22954,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا أَرَادَ أَنْ يَنَامَ وَهُوَ جُنُبٌ تَوَضَّأَ وُضُوءَهُ لِلصَّلَاةِ ‏","","",""],[22955,22955,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدَيَّ ثُمَّ لَا يَجْتَنِبُ شَيْئًا مِمَّا يَجْتَنِبُ الْمُحْرِمُ ‏","","",""],[22956,22956,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏جَاءَ عَمِّي بَعْدَ مَا ‏ ‏ضُرِبَ ‏ ‏الْحِجَابُ فَأَبَيْتُ أَنْ آذَنَ لَهُ فَسَأَلْتُهُ فَقَالَ ‏ ‏ائْذَنِي لَهُ فَإِنَّهُ عَمُّكِ قُلْتُ إِنَّمَا أَرْضَعَتْنِي الْمَرْأَةُ وَلَمْ يُرْضِعْنِي الرَّجُلُ قَالَ ‏ ‏تَرِبَتْ ‏ ‏يَمِينُكِ ائْذَنِي لَهُ فَإِنَّمَا هُوَ عَمُّكِ ‏","","",""],[22957,22957,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏اخْتَصَمَ ‏ ‏عَبْدُ بْنُ زَمْعَةَ ‏ ‏وَسَعْدُ بْنُ أَبِي وَقَّاصٍ ‏ ‏عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي ابْنِ أَمَةِ ‏ ‏زَمْعَةَ ‏ ‏قَالَ ‏ ‏عَبْدٌ ‏ ‏يَا رَسُولَ اللَّهِ أَخِي ابْنُ أَمَةِ أَبِي وُلِدَ عَلَى فِرَاشِهِ وَقَالَ ‏ ‏سَعْدٌ ‏ ‏أَوْصَانِي أَخِي إِذَا قَدِمْتَ ‏ ‏مَكَّةَ ‏ ‏فَانْظُرْ ابْنَ أَمَةِ ‏ ‏زَمْعَةَ ‏ ‏فَاقْبِضْهُ فَإِنَّهُ ابْنِي فَرَأَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَبَهًا بَيِّنًا ‏ ‏بِعُتْبَةَ ‏ ‏قَالَ هُوَ لَكَ يَا ‏ ‏عَبْدُ ‏ ‏الْوَلَدُ لِلْفِرَاشِ وَاحْتَجِبِي مِنْهُ يَا ‏ ‏سَوْدَةُ ‏","","",""],[22958,22958,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي ‏ ‏خَمِيصَةٍ ‏ ‏لَهَا ‏ ‏أَعْلَامٌ ‏ ‏فَلَمَّا ‏ ‏قَضَى ‏ ‏صَلَاتَهُ قَالَ شَغَلَنِي ‏ ‏أَعْلَامُهَا ‏ ‏اذْهَبُوا بِهَا إِلَى ‏ ‏أَبِي جَهْمٍ ‏ ‏وَأْتُونِي بِأَنْبِجَانِيَّتِهِ ‏","","",""],[22959,22959,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي صَلَاتَهُ مِنْ اللَّيْلِ وَأَنَا مُعْتَرِضَةٌ بَيْنَهُ وَبَيْنَ الْقِبْلَةِ كَاعْتِرَاضِ الْجِنَازَةِ ‏","","",""],[22960,22960,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏كُنْتُ ‏ ‏أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ وَكَانَ يَغْتَسِلُ مِنْ الْقَدَحِ وَهُوَ الْفَرَقُ ‏","","",""],[22961,22961,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏اسْتَأْذَنَ ‏ ‏رَهْطٌ ‏ ‏مِنْ ‏ ‏الْيَهُودِ ‏ ‏عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا ‏ ‏السَّامُ ‏ ‏عَلَيْكَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏بَلْ ‏ ‏السَّامُ ‏ ‏عَلَيْكُمْ وَاللَّعْنَةُ قَالَ يَا ‏ ‏عَائِشَةُ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُحِبُّ الرِّفْقَ فِي الْأَمْرِ كُلِّهِ قَالَتْ أَلَمْ تَسْمَعْ مَا قَالُوا قَالَ فَقَدْ قُلْتُ وَعَلَيْكُمْ ‏","","",""],[22962,22962,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ يُحِبُّ الرِّفْقَ فِي الْأَمْرِ كُلِّهِ ‏","","",""],[22963,22963,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ ‏ ‏تُحِدُّ ‏ ‏عَلَى مَيِّتٍ ‏ ‏فَوْقَ ‏ ‏ثَلَاثٍ إِلَّا عَلَى زَوْجٍ ‏","","",""],[22964,22964,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَهَلَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِالْحَجِّ ‏ ‏وَأَهَلَّ ‏ ‏نَاسٌ بِالْحَجِّ وَالْعُمْرَةِ ‏ ‏وَأَهَلَّ ‏ ‏نَاسٌ بِالْعُمْرَةِ ‏","","",""],[22965,22965,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَلَدُ لِلْفِرَاشِ ‏","","",""],[22966,22966,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي الْعَصْرَ وَالشَّمْسُ طَالِعَةٌ فِي حُجْرَتِي لَمْ يَظْهَرْ الْفَيْءُ بَعْدُ ‏","","",""],[22967,22967,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ نِسَاءً مِنْ الْمُؤْمِنَاتِ كُنَّ يُصَلِّينَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَ ‏ ‏مُتَلَفِّعَاتٍ ‏ ‏بِمُرُوطِهِنَّ ‏ ‏ثُمَّ يَرْجِعْنَ إِلَى أَهْلِهِنَّ وَمَا يَعْرِفُهُنَّ أَحَدٌ مِنْ ‏ ‏الْغَلَسِ ‏","","",""],[22968,22968,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏سَمِعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قِرَاءَةَ ‏ ‏أَبِي مُوسَى ‏ ‏فَقَالَ ‏ ‏لَقَدْ أُوتِيَ هَذَا مِنْ مَزَامِيرِ آلِ ‏ ‏دَاوُدَ ‏","","",""],[22969,22969,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏جَاءَتْ ‏ ‏امْرَأَةُ رِفَاعَةَ الْقُرَظِيِّ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏إِنِّي كُنْتُ عِنْدَ ‏ ‏رِفَاعَةَ ‏ ‏فَطَلَّقَنِي ‏ ‏فَبَتَّ ‏ ‏طَلَاقِي فَتَزَوَّجْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الزُّبَيْرِ ‏ ‏وَإِنَّمَا مَعَهُ مِثْلُ ‏ ‏هُدْبَةِ ‏ ‏الثَّوْبِ فَتَبَسَّمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ تُرِيدِينَ أَنْ تَرْجِعِي إِلَى ‏ ‏رِفَاعَةَ ‏ ‏لَا حَتَّى تَذُوقِي ‏ ‏عُسَيْلَتَهُ وَيَذُوقَ عُسَيْلَتَكِ ‏ ‏وَأَبُو بَكْرٍ ‏ ‏عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَالِدُ بْنُ سَعِيدِ بْنِ الْعَاصِ ‏ ‏عَلَى الْبَابِ يَنْتَظِرُ أَنْ يُؤْذَنَ لَهُ فَسَمِعَ كَلَامَهَا فَقَالَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏أَلَا تَسْمَعُ هَذِهِ مَا تَجْهَرُ بِهِ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ مَرَّةً مَا ‏ ‏تَرَى هَذِهِ تَرْفُثُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[22970,22970,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏دَخَلَ ‏ ‏مُجَزِّزٌ الْمُدْلِجِيُّ ‏ ‏عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَأَى ‏ ‏أُسَامَةَ ‏ ‏وَزَيْدًا ‏ ‏وَعَلَيْهِمَا ‏ ‏قَطِيفَةٌ ‏ ‏وَقَدْ غَطَّيَا رُءُوسَهُمَا وَبَدَتْ أَقْدَامُهُمَا فَقَالَ ‏ ‏إِنَّ هَذِهِ الْأَقْدَامَ بَعْضُهَا مِنْ بَعْضٍ ‏ ‏وَقَالَ ‏ ‏مَرَّةً دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَسْرُورًا ‏","","",""],[22971,22971,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏كَانَ ‏ ‏أَحَبُّ الشَّرَابِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحُلْوَ الْبَارِدَ ‏","","",""],[22972,22972,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏حَاضَتْ ‏ ‏صَفِيَّةُ ‏ ‏بَعْدَمَا ‏ ‏أَفَاضَتْ ‏ ‏فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَحَابِسَتُنَا ‏ ‏هِيَ قُلْتُ حَاضَتْ بَعْدَ مَا ‏ ‏أَفَاضَتْ ‏ ‏قَالَ فَلْتَنْفِرْ إِذًا ‏ ‏أَوْ قَالَ فَلَا إِذًا ‏","","",""],[22973,22973,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏وَالزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَنِي ‏ ‏أَفْلَحُ بْنُ أَبِي الْقُعَيْسِ ‏ ‏يَسْتَأْذِنُ عَلَيَّ بَعْدَمَا ضُرِبَ الْحِجَابُ وَالَّذِي أُرْضِعَتْ ‏ ‏عَائِشَةُ ‏ ‏مِنْ لَبَنِهِ هُوَ أَخُوهُ فَجَاءَ يَسْتَأْذِنُ عَلَيَّ فَأَبَيْتُ أَنْ آذَنَ لَهُ فَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏ائْذَنِي لَهُ فَإِنَّمَا هُوَ عَمُّكِ قُلْتُ إِنَّمَا أَرْضَعَتْنِي الْمَرْأَةُ وَلَمْ يُرْضِعْنِي الرَّجُلُ قَالَ ‏ ‏تَرِبَتْ ‏ ‏يَمِينُكِ هُوَ عَمُّكِ ‏","","",""],[22974,22974,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏سَمِعْتُ مِنْهُ حَدِيثًا طَوِيلًا لَيْسَ أَحْفَظُهُ مِنْ أَوَّلِهِ إِلَّا قَلِيلًا ‏ ‏دَخَلْنَا عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقُلْنَا يَا أُمَّ الْمُؤْمِنِينَ أَخْبِرِينَا عَنْ مَرَضِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏اشْتَكَى ‏ ‏فَجَعَلَ يَنْفُثُ فَجَعَلْنَا نُشَبِّهُ نَفْثَهُ ‏ ‏نَفْثَ ‏ ‏آكِلِ الزَّبِيبِ وَكَانَ يَدُورُ عَلَى نِسَائِهِ فَلَمَّا ‏ ‏اشْتَكَى ‏ ‏شَكْوَاهُ اسْتَأْذَنَهُنَّ أَنَّ يَكُونَ فِي بَيْتِ ‏ ‏عَائِشَةَ ‏ ‏وَيَدُرْنَ عَلَيْهِ فَأَذِنَّ لَهُ فَدَخَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ رَجُلَيْنِ مُتَّكِئًا عَلَيْهِمَا أَحَدُهُمَا ‏ ‏عَبَّاسٌ ‏ ‏وَرِجْلَاهُ ‏ ‏تَخُطَّانِ ‏ ‏فِي الْأَرْضِ ‏ ‏قَالَ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏أَفَمَا أَخْبَرَتْكَ مَنْ الْآخَرُ قَالَ لَا قَالَ هُوَ ‏ ‏عَلِيٌّ ‏","","",""],[22975,22975,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سُمَيٍّ ‏ ‏عَنْ ‏ ‏أَبِي بَكْرِ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُدْرِكُهُ الصُّبْحُ وَهُوَ جُنُبٌ فَيَغْتَسِلُ وَيَصُومُ ‏","","",""],[22976,22976,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُرْوَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يَقُولُ سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏بِأَيِّ شَيْءٍ طَيَّبْتِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ بِأَطْيَبِ الطِّيبِ ‏","","",""],[22977,22977,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ أَخْبَرَنَا ‏ ‏ابْنُ الْمُنْكَدِرِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ ‏ ‏أَنَّ رَجُلًا اسْتَأْذَنَ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ائْذَنُوا لَهُ فَبِئْسَ ابْنُ الْعَشِيرَةِ ‏ ‏أَوْ بِئْسَ أَخُو الْعَشِيرَةِ ‏ ‏وَقَالَ ‏ ‏مَرَّةً رَجُلٌ ‏ ‏فَلَمَّا دَخَلَ عَلَيْهِ أَلَانَ لَهُ الْقَوْلَ فَلَمَّا خَرَجَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قُلْتَ لَهُ الَّذِي قُلْتَ ثُمَّ أَلَنْتَ لَهُ الْقَوْلَ فَقَالَ أَيْ ‏ ‏عَائِشَةُ ‏ ‏شَرُّ النَّاسِ مَنْزِلَةً عِنْدَ اللَّهِ يَوْمَ الْقِيَامَةِ مَنْ وَدَعَهُ النَّاسُ ‏ ‏أَوْ تَرَكَهُ النَّاسُ ‏ ‏اتِّقَاءَ ‏ ‏فُحْشِهِ ‏","","",""],[22978,22978,"","","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الْمِسْكِ فِي رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[22979,22979,"","","‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏جَاءَتْ ‏ ‏سَهْلَةُ بِنْتُ سُهَيْلٍ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنِّي أَرَى فِي وَجْهِ ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏شَيْئًا مِنْ دُخُولِ ‏ ‏سَالِمٍ ‏ ‏عَلَيَّ فَقَالَ أَرْضِعِيهِ فَقَالَتْ كَيْفَ أُرْضِعُهُ وَهُوَ رَجُلٌ كَبِيرٌ فَضَحِكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ أَلَسْتُ أَعْلَمُ أَنَّهُ رَجُلٌ كَبِيرٌ ثُمَّ جَاءَتْ فَقَالَتْ مَا رَأَيْتُ فِي وَجْهِ ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏شَيْئًا أَكْرَهُهُ ‏","","",""],[22980,22980,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا وَحَاضَتْ ‏ ‏بِسَرِفٍ ‏ ‏قَبْلَ أَنْ تَدْخُلَ ‏ ‏مَكَّةَ ‏ ‏قَالَ لَهَا ‏ ‏اقْضِي مَا يَقْضِي الْحَاجُّ غَيْرَ أَنْ لَا تَطُوفِي ‏ ‏بِالْبَيْتِ ‏ ‏قَالَتْ فَلَمَّا كُنَّا ‏ ‏بِمِنًى ‏ ‏أُتِيتُ بِلَحْمِ بَقَرٍ قُلْتُ مَا هَذَا قَالُوا ضَحَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ أَزْوَاجِهِ بِالْبَقَرِ ‏","","",""],[22981,22981,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏أَسَمِعْتَ ‏ ‏أَبَاكَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُقَبِّلُهَا وَهُوَ صَائِمٌ فَسَكَتَ عَنِّي ‏ ‏هُنَيَّةً ‏ ‏ثُمَّ قَالَ نَعَمْ ‏","","",""],[22982,22982,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏طَيَّبْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدَيَّ هَاتَيْنِ لِحُرْمِهِ حِينَ أَحْرَمَ وَلِحِلِّهِ قَبْلَ أَنْ يَطُوفَ ‏","","",""],[22983,22983,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏خَرَجْنَا ‏ ‏لَا نَرَى إِلَّا الْحَجَّ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[22984,22984,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏حَاضَتْ ‏ ‏صَفِيَّةُ ‏ ‏فَذَكَرْتُ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏أَحَابِسَتُنَا هِيَ قُلْتُ إِنَّهَا قَدْ أَفَاضَتْ قَبْلَ ذَلِكَ قَالَ فَلَا ‏","","",""],[22985,22985,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مُسْلِمٍ يُشَاكُ بِشَوْكَةٍ فَمَا فَوْقَهَا إِلَّا ‏ ‏حَطَّتْ ‏ ‏مِنْ خَطِيئَتِهِ ‏","","",""],[22986,22986,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَمِعَ ‏ ‏ابْنَ عُمَرَ ‏ ‏حِينَ مَاتَ ‏ ‏رَافِعُ بْنُ خَدِيجٍ ‏ ‏أَنَّ بُكَاءَ الْحَيِّ عَلَى الْمَيِّتِ عَذَابٌ لِلْمَيِّتِ ‏ ‏فَأَتَيْتُ ‏ ‏عَمْرَةَ ‏ ‏فَذَكَرْتُ ذَلِكَ لَهَا فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏إِنَّمَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيَهُودِيَّةٍ ‏ ‏إِنَّكُمْ لَتَبْكُونَ عَلَيْهَا وَإِنَّهَا لَتُعَذَّبُ وَقَرَأَتْ ‏ { ‏وَلَا ‏ ‏تَزِرُ ‏ ‏وَازِرَةٌ ‏ ‏وِزْرَ ‏ ‏أُخْرَى ‏}","","",""],[22987,22987,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَبِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَيْ أُمَّتْ أَخْبِرِينِي عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ صَلَاتُهُ فِي رَمَضَانَ وَغَيْرِهِ سَوَاءً ثَلَاثَ عَشْرَةَ رَكْعَةً فِيهَا رَكْعَتَا الْفَجْرِ قُلْتُ فَأَخْبِرِينِي عَنْ صِيَامِهِ قَالَتْ كَانَ يَصُومُ حَتَّى نَقُولَ قَدْ صَامَ وَيُفْطِرُ حَتَّى نَقُولَ قَدْ أَفْطَرَ وَمَا رَأَيْتُهُ صَامَ شَهْرًا أَكْثَرَ مِنْ صِيَامِهِ فِي شَعْبَانَ كَانَ يَصُومُهُ إِلَّا قَلِيلًا ‏","","",""],[22988,22988,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏هِنْدَ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ ‏ ‏أَبَا سُفْيَانَ ‏ ‏رَجُلٌ ‏ ‏شَحِيحٌ ‏ ‏وَلَيْسَ لِي إِلَّا مَا يَدْخُلُ بَيْتِي قَالَ خُذِي مَا يَكْفِيكِ وَوَلَدَكِ ‏ ‏بِالْمَعْرُوفِ ‏","","",""],[22989,22989,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَابَقَنِي النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَبَقْتُهُ فَلَبِثْنَا حَتَّى إِذَا رَهِقَنِي اللَّحْمُ سَابَقَنِي فَسَبَقَنِي فَقَالَ هَذِهِ ‏ ‏بِتِيكِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو إِسْحَاقَ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ أَخْبَرَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّهَا كَانَتْ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي سَفَرٍ وَهِيَ جَارِيَةٌ فَقَالَ لِأَصْحَابِهِ تَقَدَّمُوا فَتَقَدَّمُوا ثُمَّ قَالَ لَهَا تَعَالَيْ أُسَابِقْكِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏","","",""],[22990,22990,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏تَبْلُغُ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا وُضِعَ الْعَشَاءُ وَأُقِيمَتْ الصَّلَاةُ فَابْدَءُوا بِالْعَشَاءِ ‏","","",""],[22991,22991,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَل ‏ ‏مَكَّةَ ‏ ‏مِنْ أَعْلَى ‏ ‏مَكَّةَ ‏ ‏وَخَرَجَ مِنْ أَسْفَلِهَا ‏","","",""],[22992,22992,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُفِّنَ فِي ثَلَاثَةِ أَثْوَابٍ ‏ ‏سُحُولِيَّةٍ ‏ ‏بِيضٍ وَقَالَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فِي أَيِّ شَيْءٍ كُفِّنَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قُلْتُ فِي ثَلَاثَةِ أَثْوَابٍ ‏ ‏قَالَ ‏ ‏كَفِّنُونِي فِي ثَوْبَيَّ هَذَيْنِ وَاشْتَرُوا ثَوْبًا آخَرَ ‏","","",""],[22993,22993,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ أَبِي سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏تَوَضَّأَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عِنْدَ ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ يَا ‏ ‏عَبْدَ الرَّحْمَنِ ‏ ‏أَسْبِغْ ‏ ‏الْوُضُوءَ فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ ‏ ‏لِلْعَرَاقِيبِ ‏ ‏مِنْ النَّارِ ‏","","",""],[22994,22994,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏ابْنِ عَجْلَانَ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ لَنَا حَصِيرَةٌ نَبْسُطُهَا بِالنَّهَارِ وَنَتَحَجَّرُهَا بِاللَّيْلِ ‏ ‏خَفِيَ عَلَيَّ شَيْءٌ لَمْ أَفْهَمْهُ مِنْ ‏ ‏سُفْيَانَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ الْمُسْلِمُونَ يُصَلُّونَ بِصَلَاتِهِ فَقَالَ ‏ ‏اكْلَفُوا ‏ ‏مِنْ الْعَمَلِ مَا تُطِيقُونَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَمَلُّ حَتَّى تَمَلُّوا وَكَانَ إِذَا صَلَّى صَلَاةً ‏ ‏أَثْبَتَهَا ‏ ‏وَكَانَ أَحَبُّ الْعَمَلِ إِلَيْهِ أَدْوَمَهُ ‏","","",""],[22995,22995,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَخِي ‏ ‏عَمْرَةَ ‏ ‏يَعْنِي هَذَا ‏ ‏مُحَمَّدَ بْنَ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخِفُّ الرَّكْعَتَيْنِ حَتَّى أَقُولَ قَرَأَ ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏أَمْ لَا ‏","","",""],[22996,22996,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنِ ‏ ‏ابْنِ أَخِي عَمْرَةَ ‏ ‏وَلَا أَدْرِي هَذَا أَوْ غَيْرَهُ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏قَالَتْ ‏ ‏اشْتَكَتْ ‏ ‏عَائِشَةُ ‏ ‏فَطَالَ شَكْوَاهَا فَقَدِمَ إِنْسَانٌ ‏ ‏الْمَدِينَةَ ‏ ‏يَتَطَبَّبُ فَذَهَبَ بَنُو أَخِيهَا يَسْأَلُونَهُ عَنْ وَجَعِهَا فَقَالَ وَاللَّهِ ‏ ‏إِنَّكُمْ تَنْعَتُونَ ‏ ‏نَعْتَ ‏ ‏امْرَأَةٍ ‏ ‏مَطْبُوبَةٍ ‏ ‏قَالَ هَذِهِ امْرَأَةٌ مَسْحُورَةٌ سَحَرَتْهَا جَارِيَةٌ لَهَا قَالَتْ نَعَمْ أَرَدْتُ أَنْ تَمُوتِي فَأُعْتَقَ قَالَ وَكَانَتْ ‏ ‏مُدَبَّرَةً ‏ ‏قَالَتْ بِيعُوهَا فِي أَشَدِّ ‏ ‏الْعَرَبِ ‏ ‏مَلَكَةً وَاجْعَلُوا ثَمَنَهَا فِي مِثْلِهَا ‏","","",""],[22997,22997,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏رَضِيعِ ‏ ‏عَائِشَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ مَيِّتٍ ‏ ‏يُصَلِّي عَلَيْهِ أُمَّةٌ مِنْ النَّاسِ يَبْلُغُونَ أَنْ يَكُونُوا مِائَةً فَيَشْفَعُونَ فِيهِ إِلَّا شُفِّعُوا فِيهِ ‏","","",""],[22998,22998,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْكَرِيمِ ‏ ‏عَنْ ‏ ‏قَيْسِ بْنِ مُسْلِمٍ الْجَدَلِيِّ ‏ ‏عَنِ ‏ ‏الْحَسَنِ بْنِ مُحَمَّدِ بْنِ عَلِيٍّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أُهْدِيَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَشِيقَةُ ‏ ‏ظَبْيٍ وَهُوَ مُحْرِمٌ فَرَدَّهَا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏الْوَشِيقَةُ مَا طُبِخَ وَقُدِّدَ ‏","","",""],[22999,22999,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ أَحَبُّ الشَّرَابِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحُلْوَ الْبَارِدَ ‏","","",""],[23000,23000,"","","‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏خَرَجَ ‏ ‏عَلْقَمَةُ ‏ ‏وَأَصْحَابُهُ حُجَّاجًا فَذَكَرَ بَعْضُهُمْ الصَّائِمَ يُقَبِّلُ ‏ ‏وَيُبَاشِرُ ‏ ‏فَقَامَ رَجُلٌ مِنْهُمْ قَدْ قَامَ سَنَتَيْنِ وَصَامَهُمَا هَمَمْتُ أَنْ آخُذَ قَوْسِي فَأَضْرِبَكَ بِهَا قَالَ فَكُفُّوا حَتَّى تَأْتُوا ‏ ‏عَائِشَةَ ‏ ‏فَدَخَلُوا عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَسَأَلُوهَا عَنْ ذَلِكَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُ ‏ ‏وَيُبَاشِرُ ‏ ‏وَكَانَ أَمْلَكَكُمْ ‏ ‏لِإِرْبِهِ ‏ ‏قَالُوا يَا ‏ ‏أَبَا شِبْلٍ ‏ ‏سَلْهَا قَالَ لَا أَرْفُثُ عِنْدَهَا الْيَوْمَ فَسَأَلُوهَا فَقَالَتْ كَانَ يُقَبِّلُ وَيُبَاشِرُ وَهُوَ صَائِمٌ ‏","","",""]];
